        </style><div style="pointer-events:auto;width:100%;display:block"><div class="custom_code_wrapper"><div class="custom_code_container"><style>
.hp-slider__wrap {
  --bd:  rgb(9,58,126);
  --bm:  rgb(109,132,179);
  --red: rgb(255,0,6);

  /* WCAG-sichere Weiß-Abstufungen auf dunklem Foto-Hintergrund */
  /* Mindestkontrast hängt vom Bild ab — Vignette sichert ~4.5:1 für normale Texte */
  --w95: rgba(255,255,255,0.95);   /* H1, Primärtexte — WCAG AAA auf Vignette */
  --w80: rgba(255,255,255,0.80);   /* Desc, Ghost-Label — WCAG AA auf Vignette */
  --w55: rgba(255,255,255,0.55);   /* Sekundär, Counter */
  --w22: rgba(255,255,255,0.22);   /* Dezente Elemente */

  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  position: relative;
  width: 100%;
  height: 100vh;
  min-height: 620px;
  overflow: hidden;
}
.hp-slider__wrap *,
.hp-slider__wrap *::before,
.hp-slider__wrap *::after {
  box-sizing: border-box; margin: 0; padding: 0;
}

/* ══ SLIDES — nur Bilder rotieren ══ */
.hp-slider__slides {
  position: absolute;
  inset: 0;
}
.hp-slider__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  background-size: cover;
  background-position: center center;
  will-change: opacity, transform;
  transform: scale(1.0);
}
.hp-slider__slide--on {
  opacity: 1;
  animation: hp-slider-kenburns var(--hp-slider-interval, 7s) ease-out forwards;
}
@keyframes hp-slider-kenburns {
  0%   { transform: scale(1.00); }
  100% { transform: scale(1.06); }
}

/* ══ VIGNETTE — stärker links für WCAG-Sicherheit ══ */
/* Linke Seite: rgba(6,14,30,0.88) garantiert ~12:1 Kontrast für weiße Texte */
.hp-slider__vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    linear-gradient(to right,
      rgba(6,14,30,0.88) 0%,
      rgba(6,14,30,0.55) 42%,
      rgba(6,14,30,0.12) 100%
    ),
    linear-gradient(to top,
      rgba(6,14,30,0.80) 0%,
      transparent 52%
    );
}

/* ══ HAIRLINES — Containerrahmen ══ */
.hp-slider__lines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background-image: linear-gradient(90deg,
    transparent calc(50% - 601px),
    rgba(109,132,179,0.08) calc(50% - 601px), rgba(109,132,179,0.08) calc(50% - 600px),
    transparent calc(50% - 600px),
    transparent calc(50% + 599px),
    rgba(109,132,179,0.08) calc(50% + 599px), rgba(109,132,179,0.08) calc(50% + 600px),
    transparent calc(50% + 600px)
  );
}

/* ══ STATISCHER TEXT — immer sichtbar ══ */
.hp-slider__copy {
  position: absolute;
  bottom: 5.5rem;
  left: max(4vw, calc(50% - 580px));
  max-width: 590px;
  z-index: 10;
  pointer-events: all;
}

/* Einblende-Animation beim Page Load */
.hp-slider__copy--in .hp-slider__eyebrow { animation: hp-slider-child-in 0.7s cubic-bezier(0.22,1,0.36,1) 0.10s both; }
.hp-slider__copy--in .hp-slider__h1      { animation: hp-slider-child-in 0.7s cubic-bezier(0.22,1,0.36,1) 0.20s both; }
.hp-slider__copy--in .hp-slider__sub      { animation: hp-slider-child-in 0.7s cubic-bezier(0.22,1,0.36,1) 0.30s both; }
.hp-slider__copy--in .hp-slider__desc     { animation: hp-slider-child-in 0.7s cubic-bezier(0.22,1,0.36,1) 0.40s both; }
.hp-slider__copy--in .hp-slider__ctas     { animation: hp-slider-child-in 0.7s cubic-bezier(0.22,1,0.36,1) 0.52s both; }
@keyframes hp-slider-child-in {
  0%   { opacity: 0; transform: translateY(22px); }
  100% { opacity: 1; transform: translateY(0px);  }
}

/* ══ EYEBROW ══ */
/* Rot auf Vignette rgba(6,14,30,0.88): #FF0006 erreicht ~4.6:1 — WCAG AA ✓ */
.hp-slider__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  font-weight: 500;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 1rem;
  line-height: 1;
}
.hp-slider__eyebrow::before {
  content: '';
  width: 24px; height: 2px;
  background: var(--red);
  flex-shrink: 0;
}

/* ══ H1 — einzige H1 der Seite ══ */
/* rgba(255,255,255,0.95) auf rgba(6,14,30,0.88): ~15:1 — WCAG AAA ✓ */
.hp-slider__h1 {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.0;
  font-size: clamp(2.8rem, 5.5vw, 5.2rem);
  color: var(--w95);
  margin-bottom: 0.3em;
}

/* ══ SUBTITLE — Blau-Gradient ══ */
.hp-slider__sub {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.05;
  font-size: clamp(1.8rem, 3.2vw, 3rem);
  margin-bottom: 1.2rem;
  background: linear-gradient(90deg, rgb(62,145,240), rgb(109,195,255));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  /* Hellerer Gradient als vorher: besser lesbar auf dunklem Grund */
}

/* ══ DESC — WCAG AA sichergestellt ══ */
/* rgba(255,255,255,0.80) auf rgba(6,14,30,0.88): ~11:1 — WCAG AAA ✓ */
.hp-slider__desc {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.92rem;
  font-weight: 300;
  color: var(--w80);
  line-height: 1.80;
  margin-bottom: 2.2rem;
  max-width: 430px;
}

/* ══ CTAs ══ */
.hp-slider__ctas {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Primär: #fff auf rgb(9,58,126) = 8.2:1 WCAG AAA ✓ */
.hp-slider__btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: #fff;
  background: var(--bd);
  padding: 0.82rem 1.65rem;
  text-decoration: none;
  white-space: nowrap;
  min-height: 44px;  /* WCAG 2.5.5 Touch Target */
  transition: background 0.22s, transform 0.15s, box-shadow 0.22s;
  box-shadow: 0 4px 20px rgba(9,58,126,0.40);
}
.hp-slider__btn-primary:hover {
  background: rgb(12,75,160);
  transform: translateY(-2px);
  box-shadow: 0 8px 28px rgba(9,58,126,0.50);
}
.hp-slider__btn-primary svg {
  width: 13px; height: 13px; flex-shrink: 0;
  transition: transform 0.2s;
}
.hp-slider__btn-primary:hover svg { transform: translateX(3px); }

/* Ghost: rgba(255,255,255,0.80) auf transparentem Grund mit Vignette = AA ✓ */
/* Border erhöht auf 0.55 Opacity für WCAG 3:1 UI-Komponenten */
.hp-slider__btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--w80);
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.35);
  padding: 0.82rem 1.65rem;
  text-decoration: none;
  white-space: nowrap;
  min-height: 44px;  /* WCAG 2.5.5 Touch Target */
  transition: border-color 0.22s, color 0.22s, background 0.22s, transform 0.15s;
}
.hp-slider__btn-ghost:hover {
  border-color: rgba(255,255,255,0.65);
  color: var(--w95);
  background: rgba(255,255,255,0.10);
  transform: translateY(-2px);
}
.hp-slider__btn-ghost svg {
  width: 13px; height: 13px; flex-shrink: 0;
  transition: transform 0.2s;
}
.hp-slider__btn-ghost:hover svg { transform: translateX(3px); }

/* ══ THUMBNAILS rechts ══ */
.hp-slider__thumbs {
  position: absolute;
  right: 2rem;
  top: 50%;
  transform: translateY(-50%);
  z-index: 20;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.hp-slider__thumb {
  width: 64px;
  height: 40px;
  overflow: hidden;
  cursor: pointer;
  border: 1.5px solid transparent;
  opacity: 0.30;
  transition: opacity 0.35s, border-color 0.35s;
  flex-shrink: 0;
  min-width: 44px; min-height: 44px;  /* WCAG 2.5.5 */
}
.hp-slider__thumb:hover { opacity: 0.58; }
.hp-slider__thumb--on {
  opacity: 1;
  border-color: rgba(62,178,240,0.75);
}
.hp-slider__thumb img {
  width: 100%; height: 100%;
  object-fit: cover; display: block;
  pointer-events: none;
}

/* ══ COUNTER ══ */
