<!-- MARKUP -->
<!--
  <header> statt <div> als Root — Hero ist semantisch der Seitenheader.
  aria-label für Screenreader da kein sichtbarer <header>-Text vorhanden.
  role="banner" ist implizit bei <header> im body-Kontext.
-->
<header class="hp-slider__wrap" id="hp-slider"
        aria-label="SONORING DORMED — Ultraschallgeräte kaufen und leasen"
        data-interval="7"
        data-fade="1200">

  <!-- NUR BILDER rotieren — kein Text im Slide, H1 bleibt statisch -->
  <div class="hp-slider__slides" aria-hidden="true">
    <div class="hp-slider__slide hp-slider__slide--on"
         style="background-image:url('/assets/img/73a6dfba-5bd9-44be-19e9-ab109c1a9e00.jpg')"></div>
    <div class="hp-slider__slide"
         style="background-image:url(' /assets/img/f8e80f5e-3f30-48b8-e2a1-4ca3667c3400.png')"></div>
    <div class="hp-slider__slide"
         style="background-image:url('/assets/img/331fb679-865c-4c8d-18a6-11f4d7c1b500.jpg')"></div>
    <div class="hp-slider__slide"
         style="background-image:url('/assets/img/ba99f24e-1ce3-4a59-f24f-5128abe68e00.png')"></div>
  </div>

  <div class="hp-slider__vignette" aria-hidden="true"></div>
  <div class="hp-slider__lines"    aria-hidden="true"></div>

  <!-- STATISCHER TEXT — H1 einzige H1 der gesamten Seite -->
  <div class="hp-slider__copy" id="hp-slider-copy">
    <p class="hp-slider__eyebrow">Ultraschall · Seit 1989</p>
    <h1 class="hp-slider__h1">Ihr Ultraschall-Fachhändler </h1>
    <p class="hp-slider__sub">für niedergelassene Ärzte</p>
    <p class="hp-slider__desc">Als größte Sonoring-Fachhändlerorganisation Deutschlands beraten wir Sie persönlich — in Dortmund, Düsseldorf, Hamburg und Kiel.</p>
    <div class="hp-slider__ctas">
