        Geräte ansehen
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2"
             stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="M3 8h10M9 4l4 4-4 4"/>
        </svg>
      </a>
      <a href="/kontakt" class="hp-slider__btn-ghost">
        Beratung anfragen
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2"
             stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="M3 8h10M9 4l4 4-4 4"/>
        </svg>
      </a>
    </div>
  </div>

  <!-- THUMBNAILS — aria-label pro Thumb für Tastaturnutzer -->
  <div class="hp-slider__thumbs" role="tablist" aria-label="Slideshow Navigation">
    <div class="hp-slider__thumb hp-slider__thumb--on"
         data-idx="0" role="tab" aria-selected="true" tabindex="0"
         aria-label="Slide 1 anzeigen">
      <img src="/assets/img/73a6dfba-5bd9-44be-19e9-ab109c1a9e00.jpg" alt="Ultraschallgerät Praxis" loading="eager">
    </div>
    <div class="hp-slider__thumb"
         data-idx="1" role="tab" aria-selected="false" tabindex="0"
         aria-label="Slide 2 anzeigen">
      <img src="/assets/img/f8e80f5e-3f30-48b8-e2a1-4ca3667c3400.png" alt="Dormed Standort Dortmund" loading="lazy">
    </div>
    <div class="hp-slider__thumb"
         data-idx="2" role="tab" aria-selected="false" tabindex="0"
         aria-label="Slide 3 anzeigen">
      <img src="/assets/img/331fb679-865c-4c8d-18a6-11f4d7c1b500.jpg" alt="SONORING DORMED Service" loading="lazy">
    </div>
    <div class="hp-slider__thumb"
         data-idx="3" role="tab" aria-selected="false" tabindex="0"
         aria-label="Slide 4 anzeigen">
      <img src="/assets/img/ba99f24e-1ce3-4a59-f24f-5128abe68e00.png" alt="Refurbished Geräte" loading="lazy">
    </div>
  </div>

  <!-- COUNTER — dekorativ, aria-hidden -->
  <div class="hp-slider__counter" aria-hidden="true">
    <b id="hp-slider-cur">01</b> / 04
  </div>

  <!-- PROGRESS BAR — dekorativ, aria-hidden -->
  <div class="hp-slider__progress" aria-hidden="true">
    <div class="hp-slider__progress-fill" id="hp-slider-prog"></div>
  </div>

</header>

<script>
(function () {
  var wrap  = document.getElementById('hp-slider');
  var copy  = document.getElementById('hp-slider-copy');
  if (!wrap) return;

  var INTERVAL_S  = parseFloat(wrap.getAttribute('data-interval')) || 7;
  var FADE_MS     = parseInt(wrap.getAttribute('data-fade'), 10)   || 1200;
  var INTERVAL_MS = INTERVAL_S * 1000;

  var slides  = wrap.querySelectorAll('.hp-slider__slide');
  var thumbs  = wrap.querySelectorAll('.hp-slider__thumb');
  var curEl   = document.getElementById('hp-slider-cur');
  var progEl  = document.getElementById('hp-slider-prog');
  var total   = slides.length;
  var current = 0;
  var busy    = false;
  var timer;

  wrap.style.setProperty('--hp-slider-interval', INTERVAL_S + 's');
  slides.forEach(function(s) {
    s.style.transition = 'opacity ' + (FADE_MS / 1000).toFixed(2) + 's ease';
  });

  function pad(n) { return n < 10 ? '0' + n : String(n); }

  function goTo(idx) {
    if (busy) return;
    var next = ((idx % total) + total) % total;
    if (next === current) return;
    busy = true;
    var prev = current;
    current  = next;

    slides[prev].classList.remove('hp-slider__slide--on');
    thumbs[prev].classList.remove('hp-slider__thumb--on');
    thumbs[prev].setAttribute('aria-selected', 'false');

    setTimeout(function() {
      slides[current].classList.remove('hp-slider__slide--on');
      void slides[current].offsetWidth;
      slides[current].classList.add('hp-slider__slide--on');
      thumbs[current].classList.add('hp-slider__thumb--on');
      thumbs[current].setAttribute('aria-selected', 'true');
      curEl.textContent = pad(current + 1);
      busy = false;
    }, 10);

    startProgress();
  }

  function startProgress() {
    progEl.style.transition = 'none';
    progEl.style.width = '0%';
    requestAnimationFrame(function() {
      requestAnimationFrame(function() {
        progEl.style.transition = 'width ' + INTERVAL_MS + 'ms linear';
        progEl.style.width = '100%';
      });
    });
  }

  function startTimer() {
    clearInterval(timer);
    timer = setInterval(function() { goTo(current + 1); }, INTERVAL_MS);
  }

  thumbs.forEach(function(thumb) {
    thumb.addEventListener('click', function() {
      goTo(parseInt(thumb.getAttribute('data-idx'), 10));
      startTimer();
    });
    /* Tastatursteuerung — Enter / Space */
    thumb.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        goTo(parseInt(thumb.getAttribute('data-idx'), 10));
        startTimer();
      }
    });
  });

  /* Text einblenden nach kurzem Delay */
  setTimeout(function() {
    if (copy) copy.classList.add('hp-slider__copy--in');
  }, 120);

  startProgress();
  startTimer();
})();
</script>
</div></div></div></div></div></div></div></section></div>
