.hp-trust__wrap {
  --dm-blue:    rgb(9,58,126);
  --dm-blue-m:  rgb(62,178,240);
  --dm-red:     rgb(255,0,6);
  --dm-text:    #060E18;
  --dm-text-2:  rgba(6,14,24,0.65);
  --dm-text-3:  rgba(6,14,24,0.40);
  --dm-border:  rgba(9,58,126,0.09);
  --dm-surface: rgba(9,58,126,0.04);
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  overflow-x: clip;
  position: relative;
}
.hp-trust__wrap *,
.hp-trust__wrap *::before,
.hp-trust__wrap *::after {
  box-sizing: border-box; margin: 0; padding: 0;
}

.hp-trust__sep-top {
  width: 100%; height: 1px;
  background: linear-gradient(90deg,
    transparent 0%, var(--dm-border) 25%,
    rgba(9,58,126,0.15) 50%, var(--dm-border) 75%, transparent 100%);
}

.hp-trust__inner {
  max-width: 1160px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* ═══ KENNZAHLEN ═══ */
.hp-trust__stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
}
.hp-trust__stat {
  padding: 2.4rem 1.5rem;
  display: flex; flex-direction: column; align-items: center;
  text-align: center; gap: 0.35rem; position: relative;
  transition: background 0.22s; cursor: default;
}
.hp-trust__stat::after {
  content: ''; position: absolute; right: 0; top: 22%; bottom: 22%;
  width: 1px; background: var(--dm-border);
}
.hp-trust__stat:last-child::after { display: none; }
.hp-trust__stat:hover { background: var(--dm-surface); }
.hp-trust__stat-num {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(2rem, 3vw, 2.8rem); font-weight: 700;
  letter-spacing: -0.04em; line-height: 1; color: var(--dm-blue);
}
.hp-trust__stat-label {
  font-family: 'JetBrains Mono', monospace; font-size: 0.6rem; font-weight: 500;
  letter-spacing: 0.18em; text-transform: uppercase; color: var(--dm-blue); line-height: 1.5;
}
.hp-trust__stat-sub {
  font-size: 0.82rem; font-weight: 400; color: var(--dm-text-2); line-height: 1.45; margin-top: 0.1rem;
}
.hp-trust__stat-accent {
  width: 24px; height: 2px; background: var(--dm-red); border-radius: 1px; margin-top: 0.2rem;
}

/* ═══ MARQUEE ═══ */
.hp-trust__marquee-header {
  display: flex; align-items: center; gap: 1rem; padding: 0.9rem 0 0.6rem;
}
.hp-trust__marquee-label {
  font-family: 'JetBrains Mono', monospace; font-size: 0.55rem; font-weight: 500;
  letter-spacing: 0.22em; text-transform: uppercase; color: var(--dm-text-2);
  white-space: nowrap; flex-shrink: 0; margin: 0;
}
.hp-trust__marquee-header-line { flex: 1; height: 1px; background: var(--dm-border); }

.hp-trust__marquee-outer {
  padding: 1.6rem 0; display: flex; align-items: center;
  overflow: hidden; position: relative;
}
.hp-trust__marquee-outer::before,
.hp-trust__marquee-outer::after {
  content: ''; position: absolute; top: 0; bottom: 0; width: 140px; z-index: 2; pointer-events: none;
}
.hp-trust__marquee-outer::before { left: 0; background: linear-gradient(90deg, #fff 0%, transparent 100%); }
.hp-trust__marquee-outer::after  { right: 0; background: linear-gradient(270deg, #fff 0%, transparent 100%); }

.hp-trust__marquee-track {
  display: flex; align-items: center;
  animation: trust-scroll 54s linear infinite;
  will-change: transform; flex-shrink: 0;
}
.hp-trust__marquee-track:hover { animation-play-state: paused; }
@keyframes trust-scroll {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.hp-trust__logo {
  display: flex; align-items: center; justify-content: center;
  padding: 0 2.8rem; opacity: 0.68;
