/* ═══ ANIMATIONEN ═══ */
.hp-trust__anim { opacity: 0; transform: translateY(12px); transition: opacity 0.65s ease, transform 0.65s ease; }
.hp-trust__anim.hp-trust__vis { opacity: 1; transform: none; }
