    entries.forEach(function(e) {
      if (e.isIntersecting) {
        e.target.classList.add('hp-trust__vis');
        obs.unobserve(e.target);
      }
    });
  }, { threshold: 0.08, rootMargin: '0px 0px -20px 0px' });
  document.querySelectorAll('.hp-trust__anim').forEach(function(el) {
    obs.observe(el);
  });
})();
