.hp-cats__wrap {
  --blue-d: rgb(9, 58, 126);
  --blue-m: rgb(109, 132, 179);
  --red:    rgb(255, 0, 6);
  --text:   rgb(6, 14, 24);
  --muted:  rgb(72, 87, 112);
  --bg:     #F7F6F4;
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  overflow-x: clip;
  position: relative;
  background: var(--bg);
}
.hp-cats__wrap *,
.hp-cats__wrap *::before,
.hp-cats__wrap *::after {
  box-sizing: border-box; margin: 0; padding: 0;
}
.hp-cats__wrap *:focus-visible {
  outline: 2px solid var(--blue-d);
  outline-offset: 3px;
}

.hp-cats__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5rem 2rem 0;
}
.hp-cats__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: 3rem;
}
.hp-cats__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 0.8rem;
}
.hp-cats__eyebrow::before {
  content: '';
  width: 24px; height: 2px;
  background: var(--red);
  flex-shrink: 0;
}
.hp-cats__h2 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--text);
}
.hp-cats__h2 span { color: var(--blue-d); }

.hp-cats__header-link {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.6rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
  flex-shrink: 0;
  transition: color 0.2s;
  min-height: 44px;
}
.hp-cats__header-link:hover { color: var(--blue-d); }
.hp-cats__header-link svg { width: 12px; height: 12px; transition: transform 0.2s; }
.hp-cats__header-link:hover svg { transform: translateX(3px); }

/* ── GRID ── */
.hp-cats__grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  grid-template-rows: 520px;
  gap: 3px;
}

/* ── KACHEL BASE ── */
.hp-cats__card {
  position: relative;
  overflow: hidden;
  cursor: pointer;
  display: block;
  text-decoration: none;
  background: #1a2a3a;
}

/* Bild — weniger dunkel als vorher */
.hp-cats__card-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  transition: transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), filter 0.5s ease;
  /* REDUZIERT: war brightness(0.45) → jetzt 0.62 — Bild sichtbarer */
  filter: brightness(0.62) saturate(0.75);
  will-change: transform;
}
.hp-cats__card:hover .hp-cats__card-bg {
  transform: scale(1.06);
  /* Hover leicht dunkler damit Text lesbar bleibt */
  filter: brightness(0.48) saturate(0.55);
}

/* Overlay — deutlich reduziert */
.hp-cats__card-overlay {
  position: absolute;
  inset: 0;
  /* REDUZIERT: unterer Anker von 0.97→0.82, mittlerer von 0.65→0.40, oberer Bereich fast weg */
  background: linear-gradient(
    to top,
    rgba(6, 14, 30, 0.82) 0%,
    rgba(6, 14, 30, 0.40) 30%,
    rgba(6, 14, 30, 0.08) 60%,
    transparent 100%
  );
  transition: background 0.4s ease;
  z-index: 1;
}
.hp-cats__card:hover .hp-cats__card-overlay {
  background: linear-gradient(
    to top,
    rgba(9, 58, 126, 0.88) 0%,
    rgba(6, 14, 30, 0.60) 40%,
    rgba(6, 14, 30, 0.10) 65%,
    transparent 100%
  );
}

.hp-cats__card-stripe {
  position: absolute;
  top: 0; left: 0;
  width: 3px; height: 0;
  background: var(--red);
  z-index: 3;
  transition: height 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.hp-cats__card:hover .hp-cats__card-stripe { height: 100%; }

.hp-cats__card-num {
  position: absolute;
  top: 1.5rem; right: 1.5rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.2em;
  color: rgba(255,255,255,0.28);
  z-index: 2;
  transition: color 0.3s;
  user-select: none;
}
.hp-cats__card:hover .hp-cats__card-num { color: rgba(255,255,255,0.50); }

.hp-cats__card-content {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 2.2rem 1.8rem 2rem;
  z-index: 2;
}
.hp-cats__card-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 0.6rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.3s ease 0.05s, transform 0.3s ease 0.05s;
}
.hp-cats__card-tag::before {
  content: '';
  width: 16px; height: 1px;
  background: var(--red);
}
.hp-cats__card:hover .hp-cats__card-tag { opacity: 1; transform: none; }

.hp-cats__card-title {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  font-size: clamp(1.1rem, 1.8vw, 1.5rem);
  letter-spacing: -0.03em;
  line-height: 1.1;
  color: rgba(255,255,255,0.95);
  margin-bottom: 0.5rem;
  transition: color 0.25s;
}
.hp-cats__card:hover .hp-cats__card-title { color: #fff; }
.hp-cats__card--featured .hp-cats__card-title {
  font-size: clamp(1.6rem, 2.5vw, 2.2rem);
}

.hp-cats__card-sub {
  font-size: 0.82rem;
  font-weight: 300;
  color: rgba(255,255,255,0.82);
  line-height: 1.65;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, opacity 0.35s ease;
  opacity: 0;
}
.hp-cats__card:hover .hp-cats__card-sub { max-height: 80px; opacity: 1; }

.hp-cats__card-arrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.88);
  margin-top: 1rem;
  opacity: 0;
  transform: translateX(-8px);
  transition: opacity 0.3s ease 0.1s, transform 0.3s ease 0.1s, color 0.2s;
}
.hp-cats__card-arrow svg { width: 14px; height: 14px; transition: transform 0.2s; }
.hp-cats__card:hover .hp-cats__card-arrow { opacity: 1; transform: none; color: #fff; }
.hp-cats__card:hover .hp-cats__card-arrow svg { transform: translateX(3px); }

.hp-cats__card-count {
  position: absolute;
  bottom: 1.8rem; right: 1.8rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.52rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.28);
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  transition: opacity 0.3s;
  user-select: none;
}
.hp-cats__card:hover .hp-cats__card-count { opacity: 0; }

.hp-cats__card-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 0;
}
.hp-cats__card-placeholder svg { width: 80px; height: 80px; opacity: 0.05; }

/* ── FOOTER ── */
.hp-cats__footer {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 2rem 5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}
.hp-cats__footer-text {
  font-size: 0.9rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.7;
}
.hp-cats__footer-cta {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.82rem;
  font-weight: 600;
  color: #fff;
  background: var(--blue-d);
  border: 2px solid var(--blue-d);
  padding: 0.75rem 1.8rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  transition: background 0.2s, border-color 0.2s, color 0.2s, transform 0.15s;
  white-space: nowrap;
  flex-shrink: 0;
  min-height: 44px;
}
.hp-cats__footer-cta:hover {
  background: transparent;
  color: var(--blue-d);
  transform: translateY(-2px);
}
.hp-cats__footer-cta svg { width: 13px; height: 13px; transition: transform 0.2s; }
.hp-cats__footer-cta:hover svg { transform: translateX(3px); }

/* ── ANIMATIONEN ── */
.hp-cats__anim {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 0.75s ease, transform 0.75s ease;
}
.hp-cats__anim.hp-cats__vis { opacity: 1; transform: none; }
.hp-cats__anim--d1 { transition-delay: 0.05s; }
.hp-cats__anim--d2 { transition-delay: 0.1s; }

.hp-cats__grid-anim {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}
.hp-cats__grid-anim.hp-cats__vis { opacity: 1; transform: none; }
.hp-cats__grid-anim--d1 { transition-delay: 0.1s; }
.hp-cats__grid-anim--d2 { transition-delay: 0.18s; }
.hp-cats__grid-anim--d3 { transition-delay: 0.26s; }
.hp-cats__grid-anim--d4 { transition-delay: 0.34s; }

/* ── RESPONSIVE ── */
@media (max-width: 1024px) {
  .hp-cats__grid {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 340px 340px;
  }
}
@media (max-width: 600px) {
  .hp-cats__grid {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 300px 300px;  /* war 240px */
    gap: 2px;
  }
  .hp-cats__card-title { font-size: 1rem !important; }
  .hp-cats__card-content { padding: 1.4rem 1.2rem 1.2rem; }
  .hp-cats__footer { flex-direction: column; align-items: flex-start; gap: 1rem; }
}
@media (max-width: 500px) {
  .hp-cats__grid {
    grid-template-columns: 1fr;
    grid-template-rows: repeat(4, 280px);  /* war 220px */
  }
}

/* ── MOBILE: Hover-Infos permanent sichtbar ── */
@media (hover: none), (max-width: 1024px) {
  .hp-cats__card-tag { opacity: 1; transform: none; }
  .hp-cats__card-sub { max-height: 120px; opacity: 1; }
  .hp-cats__card-arrow { opacity: 1; transform: none; }
  .hp-cats__card-count { opacity: 0; }
  .hp-cats__card-overlay {
    background: linear-gradient(
      to top,
      rgba(9, 58, 126, 0.85) 0%,
      rgba(6, 14, 30, 0.50) 40%,
      rgba(6, 14, 30, 0.10) 65%,
      transparent 100%
    ) !important;
  }
  .hp-cats__card-bg { filter: brightness(0.55) saturate(0.65); }
}
</style>

