.hp-fach__wrap {
  --blue-d:  rgb(9, 58, 126);
  --blue-m:  rgb(109, 132, 179);
  --red:     rgb(255, 0, 6);
  --text:    rgb(18, 30, 52);
  --muted:   rgb(72, 87, 112);
  --border:  rgba(9, 58, 126, 0.1);
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  overflow-x: clip;
  position: relative;
}
.hp-fach__wrap *,
.hp-fach__wrap *::before,
.hp-fach__wrap *::after {
  box-sizing: border-box; margin: 0; padding: 0;
}
.hp-fach__wrap *:focus-visible {
  outline: 2px solid var(--blue-d);
  outline-offset: 3px;
}
.hp-fach__transition {
  width: 100%; height: 4px;
  background: linear-gradient(90deg, transparent 0%, var(--blue-d) 30%, var(--blue-m) 70%, transparent 100%);
  opacity: 0.2;
}
.hp-fach__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5.5rem 2rem;
}
.hp-fach__header {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: end;
  margin-bottom: 4rem;
}
.hp-fach__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 0.9rem;
}
.hp-fach__eyebrow::before {
  content: '';
  width: 24px; height: 2px;
  background: var(--red);
  flex-shrink: 0;
}
.hp-fach__h2 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(1.9rem, 3.2vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--text);
}
.hp-fach__h2 span {
  color: var(--blue-d);
}
.hp-fach__header-right {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 1.2rem;
}
.hp-fach__header-desc {
  font-size: 0.9rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.8;
  max-width: 420px;
}
.hp-fach__header-note {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.55rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(9,58,126,0.35);
}
.hp-fach__header-note::before {
  content: '';
  width: 20px; height: 1px;
  background: rgba(9,58,126,0.2);
}
.hp-fach__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5px;
}
.hp-fach__card {
  background: rgba(255,255,255,0.7);
  border: 1px solid var(--border);
  border-right: none;
  padding: 2.8rem 2rem 2.2rem;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0;
  transition: background 0.3s, border-color 0.3s, transform 0.25s;
  cursor: pointer;
}
.hp-fach__card:last-child { border-right: 1px solid var(--border); }
.hp-fach__card:hover {
  background: #fff;
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(9,58,126,0.1);
  border-color: rgba(9,58,126,0.2);
  z-index: 2;
}
.hp-fach__card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--blue-d), var(--blue-m));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.hp-fach__card:hover::before { transform: scaleX(1); }
.hp-fach__card-ornament {
  position: absolute;
  bottom: -20px; right: -20px;
  width: 120px; height: 120px;
  border: 1.5px solid rgba(9,58,126,0.05);
  transition: transform 0.4s ease, opacity 0.3s;
  pointer-events: none;
}
.hp-fach__card-ornament::before {
  content: '';
  position: absolute;
  top: 15px; left: 15px; right: 15px; bottom: 15px;
  border: 1px solid rgba(9,58,126,0.04);
}
.hp-fach__card:hover .hp-fach__card-ornament {
  transform: rotate(15deg) scale(1.1);
  opacity: 0.6;
}
.hp-fach__card-icon {
  width: 52px; height: 52px;
  background: rgba(9,58,126,0.06);
  border: 1px solid rgba(9,58,126,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.8rem;
  transition: background 0.3s, border-color 0.3s;
  flex-shrink: 0;
}
.hp-fach__card-icon svg {
  width: 24px; height: 24px;
  stroke: var(--blue-d);
  transition: stroke 0.2s;
}
.hp-fach__card:hover .hp-fach__card-icon {
  background: var(--blue-d);
  border-color: var(--blue-d);
}
.hp-fach__card:hover .hp-fach__card-icon svg { stroke: white; }
.hp-fach__card-num {
  position: absolute;
  top: 1.5rem; right: 1.5rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.18em;
  color: rgba(9,58,126,0.15);
  transition: color 0.25s;
  user-select: none;
}
.hp-fach__card:hover .hp-fach__card-num { color: rgba(9,58,126,0.35); }
/* Tag: dekorativ — aria-hidden im HTML */
.hp-fach__card-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 0.5rem;
  opacity: 0;
  transform: translateX(-6px);
  transition: opacity 0.25s, transform 0.25s;
}
.hp-fach__card:hover .hp-fach__card-tag { opacity: 1; transform: none; }
/* H3: rgb(18,30,52) auf #fff = 18.4:1 ✓ AAA */
.hp-fach__card-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.15;
  color: var(--text);
  margin-bottom: 0.9rem;
  transition: color 0.2s;
}
.hp-fach__card:hover .hp-fach__card-title { color: var(--blue-d); }
/* Desc: rgb(72,87,112) auf #fff = 5.5:1 ✓ AA */
.hp-fach__card-desc {
  font-size: 0.82rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.75;
  flex: 1;
  margin-bottom: 1.5rem;
}
/* Keywords: rgb(9,58,126) = 8.2:1 ✓ AAA — WCAG FIX: war rgba(9,58,126,0.45) = 2.8:1 FAIL */
.hp-fach__card-keywords {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-bottom: 1.5rem;
}
.hp-fach__card-kw {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.52rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--blue-d);
  background: rgba(9,58,126,0.06);
  border: 1px solid rgba(9,58,126,0.12);
  padding: 0.22rem 0.55rem;
  transition: background 0.2s, border-color 0.2s;
}
.hp-fach__card:hover .hp-fach__card-kw {
  background: rgba(9,58,126,0.10);
  border-color: rgba(9,58,126,0.2);
}
/* CTA: aria-hidden — Screenreader nutzt aria-label der Card */
.hp-fach__card-cta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.25s 0.05s, transform 0.25s 0.05s;
  margin-top: auto;
}
.hp-fach__card-cta svg { width: 12px; height: 12px; transition: transform 0.2s; flex-shrink: 0; }
.hp-fach__card:hover .hp-fach__card-cta { opacity: 1; transform: none; }
.hp-fach__card:hover .hp-fach__card-cta svg { transform: translateX(3px); }
/* Devices: rgb(72,87,112) = 5.5:1 ✓ AA — WCAG FIX: war rgba(9,58,126,0.3) = 2.4:1 FAIL */
.hp-fach__card-devices {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-top: 0.8rem;
  padding-top: 0.8rem;
  border-top: 1px solid rgba(9,58,126,0.08);
  line-height: 1.7;
}
.hp-fach__bottom {
  margin-top: 3.5rem;
  padding: 2.2rem 2.5rem;
  background: rgba(9,58,126,0.04);
  border: 1px solid rgba(9,58,126,0.08);
  display: flex;
  align-items: center;
  gap: 3rem;
  position: relative;
  overflow: hidden;
}
.hp-fach__bottom::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom, var(--blue-d), var(--blue-m));
}
.hp-fach__bottom-icon {
  width: 48px; height: 48px;
  background: var(--blue-d);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.hp-fach__bottom-icon svg { width: 22px; height: 22px; stroke: white; }
.hp-fach__bottom-text { flex: 1; }
.hp-fach__bottom-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.3rem;
  letter-spacing: -0.02em;
}
.hp-fach__bottom-sub {
  font-size: 0.82rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.65;
}
.hp-fach__bottom-cta {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.82rem;
  font-weight: 600;
  color: #fff;
  background: var(--blue-d);
  border: 2px solid var(--blue-d);
  padding: 0.75rem 1.8rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s, color 0.2s;
  white-space: nowrap;
  flex-shrink: 0;
  min-height: 44px;
}
.hp-fach__bottom-cta:hover {
  background: transparent;
  color: var(--blue-d);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(9,58,126,0.15);
}
.hp-fach__bottom-cta svg { width: 13px; height: 13px; transition: transform 0.2s; }
.hp-fach__bottom-cta:hover svg { transform: translateX(3px); }
.hp-fach__anim {
  opacity: 0; transform: translateY(16px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.hp-fach__anim.hp-fach__vis { opacity: 1; transform: none; }
.hp-fach__anim--d1 { transition-delay: 0.05s; }
.hp-fach__anim--d2 { transition-delay: 0.12s; }
.hp-fach__card-anim {
  opacity: 0; transform: translateY(20px);
  transition: opacity 0.75s ease, transform 0.75s ease;
}
.hp-fach__card-anim.hp-fach__vis { opacity: 1; transform: none; }
.hp-fach__card-anim--d1 { transition-delay: 0.08s; }
.hp-fach__card-anim--d2 { transition-delay: 0.16s; }
.hp-fach__card-anim--d3 { transition-delay: 0.24s; }
.hp-fach__card-anim--d4 { transition-delay: 0.32s; }
@media (hover: none) {
  .hp-fach__card-tag { opacity: 1; transform: none; }
