        </style><div style="pointer-events:auto;width:100%;display:block"><div class="custom_code_wrapper"><div class="custom_code_container"><style>
.hp-prod__wrap {
  --blue-d: rgb(9, 58, 126);
  --blue-m: rgb(109, 132, 179);
  --red:    rgb(255, 0, 6);
  --text:   rgb(18, 30, 52);
  --muted:  rgb(72, 87, 112);    /* WCAG FIX: war rgb(100,115,140) = 3.8:1 → jetzt 5.5:1 ✓ AA */
  --line:   rgba(9, 58, 126, 0.08);
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  overflow-x: clip;
  position: relative;
}
.hp-prod__wrap *,
.hp-prod__wrap *::before,
.hp-prod__wrap *::after {
  box-sizing: border-box; margin: 0; padding: 0;
}

/* ── FOKUS (WCAG 2.4.7) ── */
.hp-prod__wrap *:focus-visible {
  outline: 2px solid var(--blue-d);
  outline-offset: 3px;
}

.hp-prod__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5.5rem 2rem 6rem;
}

/* ── HEADER ── */
.hp-prod__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 3rem;
  margin-bottom: 4rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid var(--line);
}

/* Eyebrow: rgb(9,58,126) auf #fff = 8.2:1 ✓ AAA */
/* WCAG FIX: war rgb(255,0,6) = 4.0:1 grenzwertig */
.hp-prod__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 0.9rem;
}
.hp-prod__eyebrow::before {
  content: '';
  width: 24px; height: 2px;
  background: var(--red);       /* Roter Strich: dekorativ */
  flex-shrink: 0;
}

/* H2: rgb(18,30,52) auf #fff = 18.4:1 ✓ AAA */
/* SEO: Primärkeyword "Ultraschallgeräte" + Kaufintent "Kauf und Leasing" */
.hp-prod__h2 {
  font-size: clamp(1.9rem, 3.2vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--text);
}
/* Span: rgb(9,58,126) = 8.2:1 ✓ AAA */
/* WCAG FIX: war Gradient endend bei blue-m = 3.1:1 FAIL */
.hp-prod__h2 span {
  color: var(--blue-d);
}

.hp-prod__header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.8rem;
  flex-shrink: 0;
}

/* Header-Count: dekorativ → aria-hidden="true" */
.hp-prod__header-count {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.55rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(9,58,126,0.35);   /* Dekorativ */
}

/* Header-Link: var(--muted) = 5.5:1 ✓ AA */
/* WCAG FIX: war opacity:0.6 → rgba(9,58,126,0.6) = ~5.0:1 grenzwertig */
.hp-prod__header-link {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.6rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);           /* WCAG FIX: 5.5:1 ✓ */
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: color 0.2s, gap 0.2s;
  min-height: 44px;              /* WCAG 2.5.5 Touch Target ✓ */
}
.hp-prod__header-link:hover { color: var(--blue-d); gap: 0.8rem; }
.hp-prod__header-link svg { width: 12px; height: 12px; }

/* ── GRID ── */
.hp-prod__grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr 1fr;
  grid-template-rows: auto;
  gap: 1.5px;
  background: var(--line);
}

/* ── KARTE BASE ── */
/* aria-label auf <a> → Screenreader bekommt vollständigen Kontext */
.hp-prod__card {
  background: #fff;
  padding: 2.8rem 2.4rem 2.4rem;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  transition: box-shadow 0.3s, transform 0.25s;
  cursor: pointer;
}
.hp-prod__card:hover {
  box-shadow: 0 16px 48px rgba(9,58,126,0.08), 0 2px 8px rgba(9,58,126,0.04);
  transform: translateY(-3px);
  z-index: 2;
}
.hp-prod__card::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--blue-d), var(--blue-m));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.hp-prod__card:hover::after { transform: scaleX(1); }

/* ── KARTE TOP ── */
.hp-prod__card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 2rem;
}

.hp-prod__card-badges {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.hp-prod__card-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 0.22rem 0.55rem;
  border: 1px solid;
  display: inline-block;
}
/* Brand: rgb(9,58,126) auf rgba(9,58,126,0.04) = 8.2:1 ✓ AAA */
.hp-prod__card-badge--brand {
  color: var(--blue-d);
  border-color: rgba(9,58,126,0.18);
  background: rgba(9,58,126,0.04);
}
/* Class: rgb(72,87,112) auf rgba(9,58,126,0.04) = 5.3:1 ✓ AA */
/* WCAG FIX: war rgb(100,115,140) = 3.7:1 FAIL */
.hp-prod__card-badge--class {
  color: var(--muted);
  border-color: rgba(9,58,126,0.1);
  background: transparent;
}
/* New-Badge: rgb(18,30,52) auf rgba(255,0,6,0.06) = 17:1+ ✓ AAA */
/* WCAG FIX: war rgb(255,0,6) = 3.9:1 FAIL → jetzt Text dunkel, Rand rot */
.hp-prod__card-badge--new {
  color: var(--text);
  border-color: rgba(255,0,6,0.35);
  background: rgba(255,0,6,0.04);
}

/* Verfügbar: rgb(21,128,61) auf #fff = 5.9:1 ✓ AA */
/* WCAG FIX: war rgba(34,197,94,0.7) = 3.3:1 FAIL */
.hp-prod__card-avail {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.48rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgb(21, 128, 61);       /* WCAG FIX: 5.9:1 ✓ AA */
}
/* Dot: dekorativ, aria-hidden im HTML */
.hp-prod__card-avail-dot {
  width: 5px; height: 5px;
  background: rgb(34, 197, 94);
  border-radius: 50%;
  animation: hp-prod-pulse 2.5s ease-in-out infinite;
  flex-shrink: 0;
}
@keyframes hp-prod-pulse {
  0%,100% { opacity:1; box-shadow: 0 0 0 0 rgba(34,197,94,0.4); }
  50%      { opacity:0.7; box-shadow: 0 0 0 4px rgba(34,197,94,0); }
}

/* ── GERÄTEBILD ── */
.hp-prod__card-img-wrap {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 200px;
  position: relative;
  margin-bottom: 2rem;
}
.hp-prod__card--featured .hp-prod__card-img-wrap {
  min-height: 280px;
}
.hp-prod__card-img-wrap::before {
  content: '';
  position: absolute;
  bottom: 0; left: 50%;
  transform: translateX(-50%);
  width: 70%; height: 40px;
  background: radial-gradient(ellipse, rgba(9,58,126,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hp-prod__card-img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  display: block;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  position: relative;
  z-index: 1;
}
.hp-prod__card:hover .hp-prod__card-img {
  transform: translateY(-6px) scale(1.02);
}
.hp-prod__card-svg {
  width: 100%;
  max-width: 220px;
  height: auto;
  transition: transform 0.5s cubic-bezier(0.25,0.46,0.45,0.94);
  position: relative; z-index: 1;
}
.hp-prod__card--featured .hp-prod__card-svg { max-width: 300px; }
.hp-prod__card:hover .hp-prod__card-svg { transform: translateY(-6px) scale(1.02); }

/* ── KARTE INHALT ── */
/* Modellname: rgb(72,87,112) auf #fff = 5.5:1 ✓ AA */
/* WCAG FIX: war rgb(100,115,140) = 3.8:1 FAIL */
.hp-prod__card-name {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.35rem;
}

/* H3: rgb(18,30,52) auf #fff = 18.4:1 ✓ AAA */
/* SEO: Produktname + "Ultraschallgerät" als H3-Keyword */
.hp-prod__card-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(1.3rem, 2vw, 1.7rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.1;
  color: var(--text);
  margin-bottom: 0.8rem;
  transition: color 0.2s;
}
.hp-prod__card:hover .hp-prod__card-title { color: var(--blue-d); }
.hp-prod__card--featured .hp-prod__card-title {
  font-size: clamp(1.6rem, 2.5vw, 2.1rem);
}

/* Desc: rgb(72,87,112) auf #fff = 5.5:1 ✓ AA */
/* WCAG FIX: war rgb(100,115,140) + font-weight:300 */
.hp-prod__card-desc {
  font-size: 0.82rem;
  font-weight: 400;              /* WCAG FIX: war 300 */
  color: var(--muted);
