  touch-action: pan-y; /* Nur vertikales Scrollen erlaubt auf der Sektion */
}
.hp-leis__wrap *,
.hp-leis__wrap *::before,
.hp-leis__wrap *::after { box-sizing: border-box; margin: 0; padding: 0; }

.hp-leis__wrap *:focus-visible {
  outline: 2px solid var(--blue-d);
  outline-offset: 3px;
}

.hp-leis__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5.5rem 2rem 6rem;
}

/* ── HEADER ── */
.hp-leis__header {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: end;
  margin-bottom: 3.5rem;
}
.hp-leis__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 0.9rem;
}
.hp-leis__eyebrow::before {
  content: '';
  width: 24px; height: 2px;
  background: var(--red);
  flex-shrink: 0;
}
.hp-leis__h2 {
  font-size: clamp(1.9rem, 3.2vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--text);
}
.hp-leis__h2 span { color: var(--blue-d); }
.hp-leis__header-desc {
  font-size: 0.88rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.85;
}

/* ══ TAB-NAVIGATION — aufgewertet, kein Sticky ══ */
.hp-leis__tabs-wrap {
  margin-bottom: 2.5rem;
  border-bottom: 2px solid rgba(9,58,126,0.10);
  overflow-x: clip;
}

.hp-leis__tabs {
  display: flex;
  gap: 0;
  position: relative;
  overscroll-behavior: none;
  -webkit-overflow-scrolling: auto; /* deaktiviert momentum scroll */
}

.hp-leis__tab {
  font-family: 'Space Grotesk', sans-serif;  /* Größer: Space Grotesk statt Mono */
  font-size: 0.88rem;                        /* War 0.6rem — jetzt deutlich größer */
  font-weight: 500;
  letter-spacing: -0.01em;
  text-transform: none;                      /* Kein uppercase mehr — besser lesbar */
  color: var(--muted);
  background: transparent;
  border: none;
  padding: 1rem 2rem;                        /* War 0.9rem 1.6rem — mehr Luft */
  cursor: pointer;
  position: relative;
  transition: color 0.2s, background 0.2s;
  min-height: 44px;
  white-space: nowrap;
  touch-action: manipulation; /* pan-x entfernt — verhindert vertikales Wackeln beim Tippen */
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

/* Unterlinie — 3px, satt blau */
.hp-leis__tab::after {
  content: '';
  position: absolute;
  bottom: -2px; left: 0; right: 0;
  height: 3px;
  background: var(--blue-d);
  opacity: 0;
  transition: opacity 0.2s ease;
}
.hp-leis__tab:hover {
  color: var(--blue-d);
  background: rgba(9,58,126,0.03);
}
.hp-leis__tab[aria-selected="true"] {
  color: var(--blue-d);
  font-weight: 700;                          /* Fetter im aktiven Zustand */
}
.hp-leis__tab[aria-selected="true"]::after { opacity: 1; }

/* Zähler-Badge neben dem Tab-Label */
.hp-leis__tab-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px; height: 18px;
  border-radius: 50%;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.48rem;
  font-weight: 500;
  background: rgba(9,58,126,0.08);
  color: var(--blue-d);
  margin-left: 0.5rem;
  vertical-align: middle;
  transition: background 0.2s, color 0.2s;
}
.hp-leis__tab[aria-selected="true"] .hp-leis__tab-count {
  background: var(--blue-d);
  color: #fff;
}

/* ── TAB-PANEL ── */
.hp-leis__panel {
  display: none;
  opacity: 0;
  transition: opacity 0.35s ease;
}
.hp-leis__panel[aria-hidden="false"] {
  display: block;
  animation: hp-leis-fadein 0.35s ease forwards;
}
@keyframes hp-leis-fadein {
  from { opacity: 0; }
  to   { opacity: 1; }
  /* translateY entfernt — verursacht Reflow/Scroll-Jump auf Mobile */
}

/* ── FEATURED GRID ── */
.hp-leis__featured {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
  margin-bottom: 3px;
}

/* ── FEATURED CARD ── */
.hp-leis__card {
  background: rgba(255,255,255,0.9);
  border: 1px solid rgba(9,58,126,0.06);
  padding: 3rem 2.8rem;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  transition: background 0.3s, box-shadow 0.3s, transform 0.25s;
}
.hp-leis__card:hover {
  background: #fff;
  box-shadow: 0 12px 40px rgba(9,58,126,0.08);
  transform: translateY(-3px);
  z-index: 2;
}
.hp-leis__card::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom, var(--blue-d), var(--blue-m));
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.35s cubic-bezier(0.25,0.46,0.45,0.94);
}
.hp-leis__card:hover::before { transform: scaleY(1); }

.hp-leis__card-bg-num {
  position: absolute;
  bottom: -0.5rem; right: 1.5rem;
  font-size: 8rem;
  font-weight: 700;
  letter-spacing: -0.06em;
  color: rgba(9,58,126,0.03);
  line-height: 1;
  pointer-events: none;
  user-select: none;
  transition: color 0.3s;
}
.hp-leis__card:hover .hp-leis__card-bg-num { color: rgba(9,58,126,0.055); }

.hp-leis__card-icon-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2.2rem;
}
.hp-leis__card-icon {
  width: 56px; height: 56px;
  background: rgba(9,58,126,0.06);
  border: 1px solid rgba(9,58,126,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.3s, border-color 0.3s;
  flex-shrink: 0;
}
.hp-leis__card-icon svg { width: 26px; height: 26px; stroke: var(--blue-d); transition: stroke 0.2s; }
.hp-leis__card:hover .hp-leis__card-icon { background: var(--blue-d); border-color: var(--blue-d); }
.hp-leis__card:hover .hp-leis__card-icon svg { stroke: #fff; }

.hp-leis__card-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(9,58,126,0.2);
  transition: color 0.25s;
}
.hp-leis__card:hover .hp-leis__card-num { color: rgba(9,58,126,0.4); }

.hp-leis__card-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--blue-d);
  margin-bottom: 0.5rem;
  opacity: 0;
  transform: translateX(-5px);
  transition: opacity 0.25s, transform 0.25s;
}
.hp-leis__card:hover .hp-leis__card-tag { opacity: 1; transform: none; }

.hp-leis__card-title {
  font-size: 1.45rem;
  font-weight: 700;
  letter-spacing: -0.035em;
  line-height: 1.1;
  color: var(--text);
  margin-bottom: 0.9rem;
  transition: color 0.2s;
}
.hp-leis__card:hover .hp-leis__card-title { color: var(--blue-d); }

.hp-leis__card-desc {
  font-size: 0.82rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.8;
  margin-bottom: 1.8rem;
}

.hp-leis__card-fin-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(9,58,126,0.05);
  border: 1px solid rgba(9,58,126,0.15);
  padding: 0.4rem 0.8rem;
  margin-bottom: 1.5rem;
  width: fit-content;
}
.hp-leis__card-fin-badge span {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.52rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--blue-d);
}

.hp-leis__card-points {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-bottom: 2rem;
  flex: 1;
  list-style: none;
  padding: 0;
}
.hp-leis__card-point {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  font-size: 0.8rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.5;
  opacity: 0;
  transform: translateX(-8px);
  transition: opacity 0.3s, transform 0.3s;
}
.hp-leis__card:hover .hp-leis__card-point { opacity: 1; transform: none; }
.hp-leis__card:hover .hp-leis__card-point:nth-child(1) { transition-delay: 0.05s; }
.hp-leis__card:hover .hp-leis__card-point:nth-child(2) { transition-delay: 0.10s; }
.hp-leis__card:hover .hp-leis__card-point:nth-child(3) { transition-delay: 0.15s; }

.hp-leis__card-point-dot {
  width: 5px; height: 5px;
  background: var(--blue-m);
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 5px;
}

.hp-leis__card-cta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: auto;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.25s 0.1s, transform 0.25s 0.1s;
}
.hp-leis__card-cta svg { width: 12px; height: 12px; transition: transform 0.2s; }
.hp-leis__card:hover .hp-leis__card-cta { opacity: 1; transform: none; }
.hp-leis__card:hover .hp-leis__card-cta svg { transform: translateX(3px); }

/* ── KOMPAKTE LISTE ── */
.hp-leis__list { display: flex; flex-direction: column; gap: 3px; }

.hp-leis__list-item {
  display: flex;
  align-items: center;
  gap: 1.8rem;
  background: rgba(255,255,255,0.9);
  border: 1px solid rgba(9,58,126,0.06);
  padding: 1.4rem 2rem;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  transition: background 0.25s, box-shadow 0.25s, transform 0.2s;
}
.hp-leis__list-item:hover {
  background: #fff;
  box-shadow: 0 6px 24px rgba(9,58,126,0.07);
  transform: translateX(4px);
  z-index: 1;
}
.hp-leis__list-item::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: var(--blue-d);
  transform: scaleY(0);
  transform-origin: center;
  transition: transform 0.25s;
}
.hp-leis__list-item:hover::before { transform: scaleY(1); }

.hp-leis__list-icon {
  width: 40px; height: 40px;
  background: rgba(9,58,126,0.05);
  border: 1px solid rgba(9,58,126,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 0.25s, border-color 0.25s;
}
.hp-leis__list-icon svg { width: 18px; height: 18px; stroke: var(--blue-d); transition: stroke 0.2s; }
.hp-leis__list-item:hover .hp-leis__list-icon { background: var(--blue-d); border-color: var(--blue-d); }
.hp-leis__list-item:hover .hp-leis__list-icon svg { stroke: #fff; }

.hp-leis__list-content { flex: 1; min-width: 0; }
.hp-leis__list-title {
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
  margin-bottom: 0.2rem;
  transition: color 0.2s;
}
.hp-leis__list-item:hover .hp-leis__list-title { color: var(--blue-d); }
.hp-leis__list-desc {
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.6;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hp-leis__list-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.45rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text);
  border: 1px solid rgba(255,0,6,0.35);
  background: rgba(255,0,6,0.04);
  padding: 0.18rem 0.5rem;
  flex-shrink: 0;
  white-space: nowrap;
}

.hp-leis__list-arrow {
  flex-shrink: 0;
  color: var(--blue-d);
  opacity: 0;
  transition: opacity 0.2s, transform 0.2s;
}
.hp-leis__list-arrow svg { width: 14px; height: 14px; }
.hp-leis__list-item:hover .hp-leis__list-arrow { opacity: 1; transform: translateX(3px); }

/* ── BANNER ── */
.hp-leis__banner {
  margin-top: 3px;
  background: #fff;
  border: 1px solid rgba(9,58,126,0.06);
  padding: 2rem 2.8rem;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 2.5rem;
  align-items: center;
}
.hp-leis__banner-icon {
  width: 48px; height: 48px;
  background: var(--blue-d);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.hp-leis__banner-icon svg { width: 22px; height: 22px; stroke: #fff; }
.hp-leis__banner-title {
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
  margin-bottom: 0.25rem;
}
.hp-leis__banner-sub {
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.65;
}
.hp-leis__banner-stats { display: flex; gap: 2.5rem; flex-shrink: 0; }
.hp-leis__banner-stat { text-align: center; }
.hp-leis__banner-stat-num {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.04em;
  color: var(--blue-d);
  line-height: 1;
}
.hp-leis__banner-stat-num em { font-style: normal; color: var(--red); }
.hp-leis__banner-stat-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.48rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(9,58,126,0.35);
  margin-top: 0.2rem;
}

/* ── ANIMATIONEN ── */
.hp-leis__anim {
  opacity: 0; transform: translateY(16px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.hp-leis__anim.hp-leis__vis { opacity: 1; transform: none; }
.hp-leis__anim--d1 { transition-delay: 0.05s; }
.hp-leis__anim--d2 { transition-delay: 0.12s; }

/* ── TOUCH OVERRIDES ── */
.hp-leis__wrap--touch .hp-leis__card-tag,
.hp-leis__wrap--touch .hp-leis__card-cta { opacity: 1; transform: none; transition: none; }
.hp-leis__wrap--touch .hp-leis__card-point { opacity: 1; transform: none; transition: none; }
.hp-leis__wrap--touch .hp-leis__card-icon { background: var(--blue-d); border-color: var(--blue-d); }
.hp-leis__wrap--touch .hp-leis__card-icon svg { stroke: #fff; }
.hp-leis__wrap--touch .hp-leis__card::before { transform: scaleY(1); }
.hp-leis__wrap--touch .hp-leis__card { background: #fff; box-shadow: 0 4px 20px rgba(9,58,126,0.06); }
.hp-leis__wrap--touch .hp-leis__list-arrow { opacity: 1; }
.hp-leis__wrap--touch .hp-leis__list-item::before { transform: scaleY(1); }
.hp-leis__wrap--touch .hp-leis__list-item { background: #fff; }

/* ── RESPONSIVE ── */
@media (max-width: 900px) {
  .hp-leis__header { grid-template-columns: 1fr; gap: 1.5rem; }
  .hp-leis__featured { grid-template-columns: 1fr; }
  .hp-leis__banner { grid-template-columns: auto 1fr; }
  .hp-leis__banner-stats { display: none; }
}
@media (max-width: 600px) {
  .hp-leis__inner { padding: 4rem 1.2rem 5rem; }
  .hp-leis__card { padding: 2.2rem 1.8rem; }
  .hp-leis__banner { grid-template-columns: 1fr; gap: 1.2rem; padding: 1.8rem; }
  .hp-leis__banner-icon { display: none; }
  .hp-leis__list-desc { white-space: normal; }
  .hp-leis__tab { padding: 0.8rem 1.2rem; font-size: 0.78rem; }
}
@media (max-width: 480px) {
  .hp-leis__tabs {
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    overscroll-behavior-x: contain;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }
  .hp-leis__tabs::-webkit-scrollbar { display: none; }
  .hp-leis__tab { scroll-snap-align: start; flex-shrink: 0; }
}
</style>

<section class="hp-leis__wrap" id="hp-leis" aria-label="Unsere Leistungen rund um Ultraschall">
<div class="hp-leis__inner">

  <!-- HEADER -->
  <div class="hp-leis__header hp-leis__anim hp-leis__anim--d1">
    <div>
      <div class="hp-leis__eyebrow" aria-hidden="true">Unser Service</div>
      <h2 class="hp-leis__h2">Leistungen rund um<br><span>Ihren Ultraschall</span></h2>
    </div>
    <div><p class="hp-leis__header-desc">Von der ersten Beratung über Finanzierung und Installation bis zu Wartung und Netzwerkanbindung — SONORING DORMED begleitet Sie durch jeden Schritt. Über 30 Jahre Erfahrung, vier Standorte, ~1.700 aktive Wartungsverträge.</p></div>
  </div>

  <!-- TAB-NAVIGATION — inline, kein Sticky -->
  <div class="hp-leis__tabs-wrap hp-leis__anim hp-leis__anim--d1">
    <div role="tablist" aria-label="Leistungen nach Kaufphase" class="hp-leis__tabs">
      <button id="leis-tab-1" role="tab" aria-selected="true"  aria-controls="leis-panel-1" class="hp-leis__tab">
        Vor dem Kauf <span class="hp-leis__tab-count" aria-hidden="true">2</span>
      </button>
      <button id="leis-tab-2" role="tab" aria-selected="false" aria-controls="leis-panel-2" class="hp-leis__tab">
        Beim Kauf <span class="hp-leis__tab-count" aria-hidden="true">3</span>
      </button>
      <button id="leis-tab-3" role="tab" aria-selected="false" aria-controls="leis-panel-3" class="hp-leis__tab">
        Nach dem Kauf <span class="hp-leis__tab-count" aria-hidden="true">3</span>
      </button>
    </div>
  </div>

  <!-- ═══ TAB 1: VOR DEM KAUF ═══ -->
  <div id="leis-panel-1" role="tabpanel" aria-labelledby="leis-tab-1" aria-hidden="false" class="hp-leis__panel">
    <div class="hp-leis__featured">

      <a href="/leistungen/beratung" class="hp-leis__card" aria-label="Leistung: Ultraschall Beratung — mehr erfahren">
        <div class="hp-leis__card-bg-num" aria-hidden="true">01</div>
        <div class="hp-leis__card-icon-row">
          <div class="hp-leis__card-icon" aria-hidden="true">
            <svg viewBox="0 0 24 24" fill="none" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20.25 8.511c.884.284 1.5 1.128 1.5 2.097v4.286c0 1.136-.847 2.1-1.98 2.193-.34.027-.68.052-1.02.072v3.091l-3-3c-1.354 0-2.694-.055-4.02-.163a2.115 2.115 0 0 1-.825-.242m9.345-8.334a2.126 2.126 0 0 0-.476-.095 48.64 48.64 0 0 0-8.048 0c-1.131.094-1.976 1.057-1.976 2.192v4.286c0 .837.46 1.58 1.155 1.951m9.345-8.334V6.637c0-1.621-1.152-3.026-2.76-3.235A48.455 48.455 0 0 0 11.25 3c-2.115 0-4.198.137-6.24.402-1.608.209-2.76 1.614-2.76 3.235v6.226c0 1.621 1.152 3.026 2.76 3.235.577.075 1.157.14 1.74.194V21l4.155-4.155"/></svg>
          </div>
          <span class="hp-leis__card-num" aria-hidden="true">01</span>
        </div>
        <div class="hp-leis__card-tag" aria-hidden="true">Kostenlos & unverbindlich</div>
        <h3 class="hp-leis__card-title">Ultraschall Beratung</h3>
        <p class="hp-leis__card-desc">Welches Ultraschallgerät passt zu Ihrer Praxis? Unsere Fachberater analysieren Ihren Bedarf, Ihr Fachgebiet und Ihr Budget — persönlich, telefonisch oder in unserem Showroom.</p>
        <ul class="hp-leis__card-points">
          <li class="hp-leis__card-point"><div class="hp-leis__card-point-dot" aria-hidden="true"></div>Individuelle Bedarfsanalyse nach Fachgebiet</li>
          <li class="hp-leis__card-point"><div class="hp-leis__card-point-dot" aria-hidden="true"></div>Gerätevorführung in einem unserer vier Showrooms</li>
          <li class="hp-leis__card-point"><div class="hp-leis__card-point-dot" aria-hidden="true"></div>Herstellerunabhängiger Vergleich — Mindray, Esaote u.v.m.</li>
        </ul>
