<script>
(function() {
  /* Touch Detection */
  var isTouch = ('ontouchstart' in window || navigator.maxTouchPoints > 0 ||
    (window.matchMedia && window.matchMedia('(pointer: coarse)').matches));
  var wrap = document.getElementById('hp-leis');
  if (wrap && isTouch) wrap.classList.add('hp-leis__wrap--touch');

  /* Tab-System */
  var tabs   = document.querySelectorAll('#hp-leis [role="tab"]');
  var panels = document.querySelectorAll('#hp-leis [role="tabpanel"]');

  function activateTab(tab) {
    tabs.forEach(function(t) {
      t.setAttribute('aria-selected', 'false');
      t.setAttribute('tabindex', '-1');
    });
    panels.forEach(function(p) { p.setAttribute('aria-hidden', 'true'); });
    tab.setAttribute('aria-selected', 'true');
    tab.setAttribute('tabindex', '0');
    /* focus() entfernt — verursacht Scroll-Jump auf Mobile */
    var panel = document.getElementById(tab.getAttribute('aria-controls'));
    if (panel) panel.setAttribute('aria-hidden', 'false');
  }

  tabs.forEach(function(tab, i) {
    tab.setAttribute('tabindex', i === 0 ? '0' : '-1');
    var didTouch = false;
    tab.addEventListener('touchmove', function(e) { e.stopPropagation(); }, { passive: true });
    tab.addEventListener('touchend', function(e) {
      e.preventDefault();
      e.stopPropagation(); /* Verhindert Scroll-Bubbling zum Parent */
      didTouch = true;
      activateTab(tab);
      setTimeout(function() { didTouch = false; }, 500);
    }, { passive: false });
    tab.addEventListener('click', function() {
      if (didTouch) return;
      activateTab(tab);
    });
    tab.addEventListener('keydown', function(e) {
      var idx = Array.prototype.indexOf.call(tabs, tab);
      if (e.key === 'ArrowRight') { e.preventDefault(); activateTab(tabs[(idx + 1) % tabs.length]); }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); activateTab(tabs[(idx - 1 + tabs.length) % tabs.length]); }
      else if (e.key === 'Home') { e.preventDefault(); activateTab(tabs[0]); }
      else if (e.key === 'End') { e.preventDefault(); activateTab(tabs[tabs.length - 1]); }
    });
  });

  /* Scroll Animations */
  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (e.isIntersecting) { e.target.classList.add('hp-leis__vis'); obs.unobserve(e.target); }
    });
  }, { threshold: 0.06, rootMargin: '0px 0px -30px 0px' });
  document.querySelectorAll('#hp-leis .hp-leis__anim').forEach(function(el) { obs.observe(el); });
})();
</script></div></div></div></div></div></div></div></section></div>
