}

/* Dekorative Glows — auf hellem Grund deutlich dezenter */
.hp-ueber__glow  { position:absolute;top:-120px;left:-80px;width:500px;height:500px;background:radial-gradient(circle,rgba(9,58,126,0.05) 0%,transparent 65%);pointer-events:none; }
.hp-ueber__glow2 { position:absolute;bottom:-100px;right:-60px;width:400px;height:400px;background:radial-gradient(circle,rgba(255,0,6,0.03) 0%,transparent 65%);pointer-events:none; }

.hp-ueber__inner {
