<script>
(function(){
  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (e.isIntersecting) {
        e.target.classList.add('hp-ueber__vis');
        obs.unobserve(e.target);
      }
    });
  }, { threshold: 0.05, rootMargin: '0px 0px -30px 0px' });
  document.querySelectorAll('#hp-ueber .hp-ueber__anim').forEach(function(el) {
    obs.observe(el);
  });
})();
