        </style><div style="pointer-events:auto;width:100%;display:block"><div class="custom_code_wrapper"><div class="custom_code_container"><style>
.hp-hers__wrap {
  --red:      rgb(255,0,6);
  --blue-d:   rgb(9,58,126);
  --accent:   rgb(9,58,126);
  --text:     rgb(18,30,52);
  --muted:    rgb(72,87,112);
  --subtle:   rgb(109,132,179);
  --border:   rgba(9,58,126,0.08);
  --card-bg:  #FFFFFF;
  /* Mindray Rot */
  --mindray-red:      rgb(195,0,0);
  --mindray-red-soft: rgba(195,0,0,0.06);
  --mindray-red-mid:  rgba(195,0,0,0.12);
  --mindray-red-chip: rgba(195,0,0,0.07);
  /* Chison Blau */
  --chison-blue:      rgb(30,100,180);
  --chison-blue-soft: rgba(30,100,180,0.06);
  --chison-blue-mid:  rgba(30,100,180,0.12);
  --chison-blue-chip: rgba(30,100,180,0.08);
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  overflow-x: clip;
  position: relative;
}
.hp-hers__wrap *,
.hp-hers__wrap *::before,
.hp-hers__wrap *::after { box-sizing: border-box; margin: 0; padding: 0; }
.hp-hers__wrap *:focus-visible { outline: 2px solid var(--blue-d); outline-offset: 3px; }

/* ── HEADER ── */
.hp-hers__header { text-align: center; margin-bottom: 5rem; }
.hp-hers__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  font-weight: 500;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 0.9rem;
}
.hp-hers__eyebrow::before,
.hp-hers__eyebrow::after { content:''; width:24px; height:2px; background:var(--blue-d); }
.hp-hers__h2 {
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--text);
  margin-bottom: 1rem;
}
.hp-hers__h2 span {
  background: linear-gradient(90deg, rgb(9,58,126), rgb(109,132,179));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hp-hers__header-sub {
  font-size: 0.85rem;
  font-weight: 400;
  color: var(--muted);
  max-width: 520px;
  margin: 0 auto;
  line-height: 1.8;
}

/* ── GRID ── */
.hp-hers__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
  margin-bottom: 3px;
}

/* ── KARTE BASE ── */
.hp-hers__card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  padding: 2.6rem 2.2rem;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  text-decoration: none;
  transition: box-shadow 0.3s, border-color 0.3s;
  cursor: pointer;
}

/* ═══════════════════════════════
   MINDRAY — Rotes Design
═══════════════════════════════ */
.hp-hers__card--mindray {
  background: linear-gradient(
    150deg,
    rgba(195,0,0,0.03) 0%,
    #ffffff 40%
  );
  border-color: rgba(195,0,0,0.12);
}
.hp-hers__card--mindray:hover {
  box-shadow: 0 8px 32px rgba(195,0,0,0.10);
  border-color: rgba(195,0,0,0.22);
  background: linear-gradient(
    150deg,
    rgba(195,0,0,0.055) 0%,
    #ffffff 40%
  );
}
.hp-hers__card--mindray::before {
  content: '';
  position: absolute;
  top: -80px; left: -80px;
  width: 320px; height: 320px;
  background: radial-gradient(circle, rgba(195,0,0,0.07) 0%, transparent 65%);
  pointer-events: none;
}
.hp-hers__card--mindray::after {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom, var(--mindray-red), rgba(195,0,0,0.3));
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.35s cubic-bezier(0.25,0.46,0.45,0.94);
}
.hp-hers__card--mindray:hover::after { transform: scaleY(1); }
.hp-hers__card--mindray:hover .hp-hers__card-title {
  color: var(--mindray-red) !important;
}
.hp-hers__card--mindray .hp-hers__card-model {
  color: var(--mindray-red);
  background: var(--mindray-red-chip);
  border-color: rgba(195,0,0,0.18);
}
.hp-hers__card--mindray:hover .hp-hers__card-model {
  background: rgba(195,0,0,0.11);
}
.hp-hers__card--mindray .hp-hers__card-feat-icon {
  background: var(--mindray-red-chip);
  border-color: rgba(195,0,0,0.18);
}
.hp-hers__card--mindray .hp-hers__card-feat-icon svg {
  stroke: var(--mindray-red);
}
.hp-hers__card--mindray:hover .hp-hers__card-feat-icon {
  background: rgba(195,0,0,0.12);
}
.hp-hers__card--mindray .hp-hers__card-cta {
  color: var(--mindray-red);
}
.hp-hers__card--mindray .hp-hers__card-since-dot {
  background: var(--mindray-red);
}

/* ═══════════════════════════════
   ESAOTE — Standard blau
═══════════════════════════════ */
.hp-hers__card--esaote::before {
  content: '';
  position: absolute;
  top: -60px; right: -60px;
  width: 280px; height: 280px;
  background: radial-gradient(circle, rgba(9,58,126,0.04) 0%, transparent 65%);
  pointer-events: none;
}
.hp-hers__card--esaote::after {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom, var(--blue-d), var(--subtle));
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.35s cubic-bezier(0.25,0.46,0.45,0.94);
}
.hp-hers__card--esaote:hover {
  box-shadow: 0 8px 32px rgba(9,58,126,0.10);
  border-color: rgba(9,58,126,0.18);
}
.hp-hers__card--esaote:hover::after { transform: scaleY(1); }
.hp-hers__card--esaote:hover .hp-hers__card-title { color: var(--blue-d) !important; }

/* ═══════════════════════════════
   CHISON — Eigenes Blau (rgb(30,100,180))
   Differenziert von Esaote-Blau (rgb(9,58,126))
═══════════════════════════════ */
.hp-hers__card--chison {
  background: linear-gradient(
    150deg,
    rgba(30,100,180,0.035) 0%,
    #ffffff 40%
  );
  border-color: rgba(30,100,180,0.14);
}
.hp-hers__card--chison:hover {
  box-shadow: 0 8px 32px rgba(30,100,180,0.12);
  border-color: rgba(30,100,180,0.26);
  background: linear-gradient(
    150deg,
    rgba(30,100,180,0.06) 0%,
    #ffffff 40%
  );
}
.hp-hers__card--chison::before {
  content: '';
  position: absolute;
  top: -80px; right: -80px;
  width: 320px; height: 320px;
  background: radial-gradient(circle, rgba(30,100,180,0.08) 0%, transparent 65%);
  pointer-events: none;
}
.hp-hers__card--chison::after {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom, var(--chison-blue), rgba(30,100,180,0.35));
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.35s cubic-bezier(0.25,0.46,0.45,0.94);
}
.hp-hers__card--chison:hover::after { transform: scaleY(1); }
.hp-hers__card--chison:hover .hp-hers__card-title {
  color: var(--chison-blue) !important;
}
.hp-hers__card--chison .hp-hers__card-model {
  color: var(--chison-blue);
  background: var(--chison-blue-chip);
  border-color: rgba(30,100,180,0.20);
}
.hp-hers__card--chison:hover .hp-hers__card-model {
  background: rgba(30,100,180,0.13);
}
.hp-hers__card--chison .hp-hers__card-feat-icon {
  background: var(--chison-blue-chip);
  border-color: rgba(30,100,180,0.20);
}
.hp-hers__card--chison .hp-hers__card-feat-icon svg {
  stroke: var(--chison-blue);
}
.hp-hers__card--chison:hover .hp-hers__card-feat-icon {
  background: rgba(30,100,180,0.14);
}
.hp-hers__card--chison .hp-hers__card-cta {
  color: var(--chison-blue);
}
.hp-hers__card--chison .hp-hers__card-since-dot {
  background: var(--chison-blue);
}

/* ── LOGO ROW ── */
.hp-hers__card-logo-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2.2rem;
  gap: 0.8rem;
}
.hp-hers__card-logo { height: 32px; display: flex; align-items: center; }
.hp-hers__card-logo svg { height: 100%; width: auto; }
.hp-hers__card-logo-img {
  height: 28px;
  width: auto;
  max-width: 140px;
  object-fit: contain;
  display: block;
}

.hp-hers__card-since {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  font-weight: 400;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--subtle);
  display: flex;
  align-items: center;
  gap: 0.4rem;
  white-space: nowrap;
}
.hp-hers__card-since-dot {
  width: 4px; height: 4px;
  background: var(--blue-d);
  border-radius: 50%;
}

/* ── CARD CONTENT ── */
.hp-hers__card-title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.1;
  color: var(--text);
  margin-bottom: 0.7rem;
  transition: color 0.2s;
}
.hp-hers__card-desc {
  font-size: 0.8rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.75;
  margin-bottom: 1.6rem;
}

.hp-hers__card-models {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-bottom: 1.8rem;
  list-style: none;
  padding: 0;
}
.hp-hers__card-model {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.48rem;
  font-weight: 400;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--blue-d);
  background: rgba(9,58,126,0.06);
  border: 1px solid rgba(9,58,126,0.12);
  padding: 0.22rem 0.55rem;
  transition: background 0.2s;
}
.hp-hers__card--esaote:hover .hp-hers__card-model { background: rgba(9,58,126,0.10); }

.hp-hers__card-feats {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin-bottom: 2rem;
  flex: 1;
  list-style: none;
  padding: 0;
}
.hp-hers__card-feat {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  font-size: 0.76rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.55;
}
.hp-hers__card-feat-icon {
  width: 18px; height: 18px;
  background: rgba(9,58,126,0.06);
  border: 1px solid rgba(9,58,126,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
  transition: background 0.2s;
}
.hp-hers__card-feat-icon svg { width: 9px; height: 9px; stroke: var(--blue-d); }
.hp-hers__card--esaote:hover .hp-hers__card-feat-icon { background: rgba(9,58,126,0.10); }

.hp-hers__card-cta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.56rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--blue-d);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: gap 0.2s;
}
.hp-hers__card-cta svg { width: 12px; height: 12px; transition: transform 0.2s; }
.hp-hers__card:hover .hp-hers__card-cta { gap: 0.8rem; }
.hp-hers__card:hover .hp-hers__card-cta svg { transform: translateX(3px); }

/* ── ZERTIFIKATE ── */
.hp-hers__certs {
  background: #FFFFFF;
  border: 1px solid var(--border);
  padding: 1.6rem 2.8rem;
  display: flex;
  align-items: center;
  gap: 3rem;
}
.hp-hers__certs-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  font-weight: 400;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--subtle);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.hp-hers__certs-label::after { content:''; flex:1; min-width:24px; height:1px; background:var(--border); }
.hp-hers__certs-row { display: flex; align-items: center; gap: 2.5rem; flex: 1; }
.hp-hers__cert {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  font-weight: 400;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: color 0.2s;
}
.hp-hers__cert:hover { color: var(--text); }
.hp-hers__cert-dot { width: 5px; height: 5px; background: var(--blue-d); border-radius: 50%; opacity: 0.4; }

/* ── ANIMATIONEN ── */
.hp-hers__anim { opacity:0; transform:translateY(18px); transition:opacity 0.75s ease,transform 0.75s ease; }
.hp-hers__anim.hp-hers__vis { opacity:1; transform:none; }
.hp-hers__anim--d1 { transition-delay:0.05s; }
.hp-hers__anim--d2 { transition-delay:0.15s; }
.hp-hers__anim--d3 { transition-delay:0.25s; }
.hp-hers__anim--d4 { transition-delay:0.35s; }

/* ── INNER / RESPONSIVE ── */
.hp-hers__inner {
  max-width: 1800px;
  margin: 0 auto;
  padding: 7rem 4rem 6rem;
}

/* Zwei-Spalten-Layout bei mittlerer Breite — dritte Karte wird full-width */
@media (max-width:1200px) {
  .hp-hers__grid {
    grid-template-columns: 1fr 1fr;
  }
  .hp-hers__card--chison {
    grid-column: 1 / -1;
  }
}

@media (max-width:900px) {
  .hp-hers__grid {
    grid-template-columns: 1fr;
  }
  .hp-hers__card--chison {
    grid-column: auto;
  }
  .hp-hers__card {
    padding: 3rem 2.8rem;
  }
  .hp-hers__card-title {
    font-size: 1.35rem;
  }
  .hp-hers__card-desc {
    font-size: 0.82rem;
  }
}

@media (max-width:600px) {
  .hp-hers__inner { padding:4.5rem 1.2rem; }
  .hp-hers__card { padding:2.2rem 1.8rem; }
  .hp-hers__certs { flex-direction:column; align-items:flex-start; gap:1.2rem; padding:1.5rem; }
  .hp-hers__certs-row { flex-wrap:wrap; gap:1rem; }
}
</style>

<section class="hp-hers__wrap" id="hp-hers" aria-label="Hersteller-Partner Ultraschall">
  <div class="hp-hers__inner">

    <header class="hp-hers__header hp-hers__anim hp-hers__anim--d1">
      <p class="hp-hers__eyebrow" aria-hidden="true">Unsere Partner</p>
      <h2 class="hp-hers__h2">Unsere Hersteller <span>- Partner</span></h2>
      <p class="hp-hers__header-sub">Wir führen kein breites Sortiment aus taktischen Gründen. Wir haben Mindray und Esaote gewählt weil wir von beiden überzeugt sind — und weil wir beide in- und auswendig kennen.</p>
    </header>

    <div class="hp-hers__grid">

      <!-- MINDRAY — rot -->
      <a href="/hersteller/mindray" class="hp-hers__card hp-hers__card--mindray hp-hers__anim hp-hers__anim--d2" aria-label="Mindray Ultraschallgeräte bei SONORING DORMED ansehen">
        <div class="hp-hers__card-logo-row">
          <div class="hp-hers__card-logo">
