.hp-kund__wrap {
  --blue-d:  rgb(9,58,126);
  --blue-m:  rgb(109,132,179);
  --text:    rgb(18,30,52);
  --muted:   rgb(72,87,112);
  --subtle:  rgb(109,132,179);
  --line:    rgba(9,58,126,0.08);
  --star:    #D97706;
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  overflow-x: clip;
}
.hp-kund__wrap *, .hp-kund__wrap *::before, .hp-kund__wrap *::after {
  box-sizing: border-box; margin: 0; padding: 0;
}
.hp-kund__wrap *:focus-visible { outline: 2px solid var(--blue-d); outline-offset: 3px; }

.hp-kund__inner { max-width: 1200px; margin: 0 auto; padding: 6rem 2rem; }

/* HEADER */
.hp-kund__header {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 3rem; margin-bottom: 3.5rem;
}
.hp-kund__eyebrow {
  font-family: 'JetBrains Mono', monospace; font-size: 0.58rem; font-weight: 500;
  letter-spacing: 0.25em; text-transform: uppercase; color: var(--blue-d);
  display: flex; align-items: center; gap: 0.7rem; margin-bottom: 0.9rem;
}
.hp-kund__eyebrow::before {
  content: ''; width: 24px; height: 2px;
  background: linear-gradient(90deg, var(--blue-d), var(--blue-m)); flex-shrink: 0;
}
.hp-kund__h2 {
  font-size: clamp(1.8rem, 3vw, 2.6rem); font-weight: 700;
  letter-spacing: -0.04em; line-height: 1.05; color: var(--text);
}
.hp-kund__h2 span {
  background: linear-gradient(90deg, var(--blue-d), var(--blue-m));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}

/* RATING BADGE */
.hp-kund__rating-badge { display: flex; flex-direction: column; align-items: flex-end; gap: 0.4rem; flex-shrink: 0; }
.hp-kund__rating-score { display: flex; align-items: center; gap: 0.6rem; }
.hp-kund__rating-num { font-size: 2.2rem; font-weight: 700; letter-spacing: -0.05em; color: var(--text); line-height: 1; }
.hp-kund__stars { display: flex; gap: 2px; }
.hp-kund__star { width: 16px; height: 16px; fill: var(--star); }
.hp-kund__rating-label { font-family: 'JetBrains Mono', monospace; font-size: 0.56rem; font-weight: 500; letter-spacing: 0.15em; text-transform: uppercase; color: var(--muted); }
.hp-kund__gbp-source { display: flex; align-items: center; gap: 0.5rem; margin-top: 0.2rem; }
.hp-kund__gbp-link {
  font-family: 'JetBrains Mono', monospace; font-size: 0.52rem; font-weight: 500;
  letter-spacing: 0.12em; text-transform: uppercase; color: var(--blue-d);
  text-decoration: none; display: inline-flex; align-items: center; gap: 0.35rem;
  border-bottom: 1px solid rgba(9,58,126,0.25); padding-bottom: 1px;
  transition: border-color 0.2s;
}
.hp-kund__gbp-link:hover { border-color: var(--blue-d); }

/* KARUSSELL */
.hp-kund__carousel { position: relative; overflow: hidden; margin-bottom: 2rem; }
.hp-kund__track { display: flex; gap: 3px; transition: transform 0.45s cubic-bezier(0.4,0,0.2,1); }

.hp-kund__card {
  flex: 0 0 calc(33.333% - 2px);
  background: #fff; border: 1px solid var(--line);
  padding: 2rem 1.8rem; display: flex; flex-direction: column; gap: 1rem;
  position: relative; overflow: hidden;
  transition: box-shadow 0.25s;
}
.hp-kund__card:hover { box-shadow: 0 8px 30px rgba(9,58,126,0.07); }
.hp-kund__card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
  background: linear-gradient(90deg, var(--blue-d), var(--blue-m));
  transform: scaleX(0); transform-origin: left; transition: transform 0.3s;
}
.hp-kund__card:hover::before { transform: scaleX(1); }
.hp-kund__card-quote-mark {
  font-family: 'Space Grotesk', sans-serif; font-size: 4rem; font-weight: 700;
  color: rgba(9,58,126,0.06); line-height: 0.8;
  position: absolute; top: 1rem; right: 1.2rem; user-select: none; pointer-events: none;
}
.hp-kund__card-stars { display: flex; gap: 2px; }
.hp-kund__card-star { width: 14px; height: 14px; fill: var(--star); }
.hp-kund__card-text { font-size: 0.82rem; font-weight: 400; color: var(--muted); line-height: 1.8; flex: 1; font-style: italic; }
.hp-kund__card-text p { margin: 0; }
.hp-kund__card-footer {
  display: flex; align-items: center; gap: 0.8rem;
  padding-top: 1rem; border-top: 1px solid var(--line);
}
.hp-kund__card-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(9,58,126,0.08); border: 1px solid rgba(9,58,126,0.12);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
  font-size: 0.75rem; font-weight: 600; color: var(--blue-d);
}
.hp-kund__card-name { font-size: 0.75rem; font-weight: 600; color: var(--text); letter-spacing: -0.01em; font-style: normal; display: block; }
.hp-kund__card-label { font-family: 'JetBrains Mono', monospace; font-size: 0.54rem; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; color: var(--subtle); margin-top: 0.1rem; display: block; }
.hp-kund__card-date { font-family: 'JetBrains Mono', monospace; font-size: 0.48rem; letter-spacing: 0.1em; color: rgba(109,132,179,0.7); margin-top: 0.05rem; display: block; }

/* CONTROLS */
.hp-kund__controls { display: flex; align-items: center; justify-content: center; gap: 1.5rem; margin-top: 2rem; }
.hp-kund__btn {
  width: 40px; height: 40px; border: 1px solid var(--line); background: #fff;
  color: var(--blue-d); display: flex; align-items: center; justify-content: center;
  cursor: pointer; transition: background 0.2s, border-color 0.2s, opacity 0.2s; flex-shrink: 0;
}
.hp-kund__btn:hover { background: rgba(9,58,126,0.05); border-color: rgba(9,58,126,0.2); }
.hp-kund__btn:disabled { opacity: 0.35; cursor: not-allowed; }
.hp-kund__btn svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.hp-kund__dots { display: flex; gap: 0.5rem; align-items: center; list-style: none; padding: 0; }
.hp-kund__dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(9,58,126,0.2); border: none; cursor: pointer; padding: 0; transition: background 0.2s, transform 0.2s; }
.hp-kund__dot--active { background: var(--blue-d); transform: scale(1.4); }

/* FOOTER */
.hp-kund__footer {
  display: flex; align-items: center; justify-content: center; gap: 1.5rem;
  margin-top: 3rem; padding-top: 2.5rem; border-top: 1px solid var(--line); flex-wrap: wrap;
}
.hp-kund__footer-meta {
  display: flex; align-items: center; gap: 0.6rem;
  font-family: 'JetBrains Mono', monospace; font-size: 0.56rem; font-weight: 500;
  letter-spacing: 0.15em; text-transform: uppercase; color: var(--subtle);
}
.hp-kund__footer-cta {
  font-family: 'JetBrains Mono', monospace; font-size: 0.58rem; font-weight: 600;
  letter-spacing: 0.14em; text-transform: uppercase; color: #fff;
  background: var(--blue-d); text-decoration: none; display: inline-flex;
  align-items: center; gap: 0.6rem; padding: 0.65rem 1.4rem;
  transition: background 0.2s, transform 0.15s;
}
.hp-kund__footer-cta:hover { background: rgb(7,46,100); transform: translateY(-1px); }
.hp-kund__footer-cta svg { width: 12px; height: 12px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* ANIMATIONEN */
.hp-kund__anim { opacity: 0; transform: translateY(16px); transition: opacity 0.7s ease, transform 0.7s ease; }
.hp-kund__anim.hp-kund__vis { opacity: 1; transform: none; }
.hp-kund__anim--d1 { transition-delay: 0.05s; }
.hp-kund__anim--d2 { transition-delay: 0.14s; }
.hp-kund__anim--d3 { transition-delay: 0.22s; }
.hp-kund__anim--d4 { transition-delay: 0.30s; }

/* RESPONSIVE */
@media(max-width:960px) {
  .hp-kund__card { flex: 0 0 calc(50% - 2px); }
  .hp-kund__header { flex-direction: column; align-items: flex-start; gap: 1rem; }
  .hp-kund__rating-badge { align-items: flex-start; }
}
@media(max-width:600px) {
  .hp-kund__inner { padding: 4rem 1.2rem; }
  .hp-kund__card { flex: 0 0 100%; }
  .hp-kund__footer { flex-direction: column; align-items: center; }
}
</style>

