<script>
(function() {
  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (e.isIntersecting) { e.target.classList.add('hp-kund__vis'); obs.unobserve(e.target); }
    });
  }, { threshold: 0.05, rootMargin: '0px 0px -30px 0px' });
  document.querySelectorAll('#hp-kund .hp-kund__anim').forEach(function(el) { obs.observe(el); });

  var track   = document.getElementById('kund-track');
  var btnPrev = document.getElementById('kund-prev');
  var btnNext = document.getElementById('kund-next');
  var dotsEl  = document.getElementById('kund-dots');
  var cards   = track ? track.querySelectorAll('.hp-kund__card') : [];
  var total   = cards.length;
  var current = 0;

  function vis() { return window.innerWidth <= 600 ? 1 : window.innerWidth <= 960 ? 2 : 3; }
  function pages() { return Math.ceil(total / vis()); }

  function buildDots() {
    dotsEl.innerHTML = '';
    var n = pages();
    for (var i = 0; i < n; i++) {
      var li = document.createElement('li');
      var btn = document.createElement('button');
      btn.className = 'hp-kund__dot' + (i === 0 ? ' hp-kund__dot--active' : '');
      btn.setAttribute('aria-label', 'Seite ' + (i+1) + ' von ' + n);
      btn.setAttribute('aria-current', i === 0 ? 'true' : 'false');
      (function(idx){ btn.addEventListener('click', function(){ goTo(idx); }); })(i);
      li.appendChild(btn); dotsEl.appendChild(li);
    }
  }

  function goTo(page) {
    var n = pages();
    current = Math.max(0, Math.min(page, n - 1));
    if (!cards.length) return;
    var cardW = cards[0].offsetWidth;
    track.style.transform = 'translateX(-' + (current * vis() * (cardW + 3)) + 'px)';
    dotsEl.querySelectorAll('.hp-kund__dot').forEach(function(d, i) {
      d.classList.toggle('hp-kund__dot--active', i === current);
      d.setAttribute('aria-current', i === current ? 'true' : 'false');
    });
    btnPrev.disabled = current === 0;
    btnNext.disabled = current >= n - 1;
  }

  if (track && total > 0) {
    buildDots(); goTo(0);
    btnPrev.addEventListener('click', function() { goTo(current - 1); });
    btnNext.addEventListener('click', function() { goTo(current + 1); });
    var rt;
    window.addEventListener('resize', function() {
      clearTimeout(rt);
      rt = setTimeout(function() { buildDots(); goTo(0); }, 150);
    }, { passive: true });
  }
})();
</script>
