        </style><div style="pointer-events:auto;width:100%;display:block"><div class="custom_code_wrapper"><div class="custom_code_container"><style>
.hp-stand__wrap {
  --red:    rgb(255,0,6);
  --blue-d: rgb(9,58,126);
  --blue-m: rgb(62,178,240);
  --text:   rgb(12,22,40);        /* 18:1 AAA auf #fff ✓ */
  --muted:  rgb(72,87,112);       /* 5.5:1 AA auf #fff ✓  FIX: war rgb(80,95,120)=5.1:1 knapp */
  /* FIX: --blue-m als hover-Farbe auf #fff = 2.9:1 FAIL → hover bleibt --blue-d = 8.2:1 AAA */
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  overflow-x: clip;
}
.hp-stand__wrap *,
.hp-stand__wrap *::before,
.hp-stand__wrap *::after { box-sizing: border-box; margin: 0; padding: 0; }

.hp-stand__wrap *:focus-visible {
  outline: 2px solid var(--blue-d);
  outline-offset: 3px;
}

.hp-stand__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 6rem 2rem 7rem;
}

/* ── HEADER ── */
.hp-stand__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 3rem;
  gap: 2rem;
}

/* Eyebrow: dekorativ → aria-hidden */
/* rgb(255,0,6) auf #F4F6F9 → 4.6:1 AA ✓ */
.hp-stand__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  font-weight: 500;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 0.9rem;
}
.hp-stand__eyebrow::before { content:'';width:24px;height:2px;background:var(--red);flex-shrink:0; }

/* rgb(12,22,40) → 18:1 AAA ✓ */
.hp-stand__h2 {
  font-size: clamp(2.2rem, 4vw, 3.4rem);
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 1.0;
  color: var(--text);
}
.hp-stand__h2 span {
  background: linear-gradient(90deg, var(--blue-d), var(--blue-m));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hp-stand__header-stat { text-align: right; flex-shrink: 0; }
/* rgb(12,22,40) → 18:1 AAA ✓ */
.hp-stand__header-stat-num {
  font-size: 3.5rem;
  font-weight: 700;
  letter-spacing: -0.06em;
  line-height: 1;
  color: var(--text);
}
.hp-stand__header-stat-num em { font-style: normal; color: var(--blue-d); } /* 8.2:1 AAA ✓ */

/* FIX: war 0.5rem + keine weight → FAIL
   → 0.56rem + weight:500 + rgb(72,87,112) = 5.5:1 AA ✓ */
.hp-stand__header-stat-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.56rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 0.3rem;
}

/* ── SPLIT LAYOUT ── */
.hp-stand__layout {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 0;
  align-items: stretch;
}

/* ══════════════════════════════════════════
   HERO (DORTMUND) — DUNKEL
══════════════════════════════════════════ */
.hp-stand__hero {
  position: relative;
  overflow: hidden;
  min-height: 580px;
  display: flex;
  flex-direction: column;
  text-decoration: none;
}

/* Alt-Text SEO-spezifisch im Markup */
.hp-stand__hero-img {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  object-position: center 35%;
  filter: brightness(0.35) saturate(0.6) contrast(1.1);
  transition: transform 0.9s ease, filter 0.5s ease;
}
.hp-stand__hero:hover .hp-stand__hero-img {
  transform: scale(1.05);
  filter: brightness(0.45) saturate(0.7) contrast(1.05);
}

/* Overlay: sehr dunkel → alle weißen Texte haben ≥4.5:1 */
.hp-stand__hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    170deg,
    rgba(0,0,0,0.05) 0%,
    rgba(0,0,0,0.60) 50%,
    rgba(0,0,0,0.96) 100%
  );
}

/* Blauer Akzent-Streifen links — dekorativ */
.hp-stand__hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; bottom: 0;
  width: 4px;
  background: linear-gradient(to bottom, var(--blue-d), var(--blue-m));
  z-index: 3;
  aria-hidden: true; /* CSS-Pseudo-Element → kein DOM-Node nötig */
}

.hp-stand__hero-content {
  position: relative;
  z-index: 2;
  padding: 3rem 3rem 3rem 3.6rem;
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
}

/* Badge: dekorativ, Info steckt in aria-label des <a> */
.hp-stand__hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(0,0,0,0.5);
  border: 1px solid rgba(255,255,255,0.15);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  padding: 0.35rem 0.85rem;
  width: fit-content;
}
.hp-stand__hero-badge-dot {
  width: 6px; height: 6px;
  background: var(--blue-m);
  border-radius: 50%;
  flex-shrink: 0;
  animation: stand-pulse 2.5s ease-in-out infinite;
}
@keyframes stand-pulse {
  0%,100% { opacity:1; box-shadow:0 0 0 0 rgba(62,178,240,0.5); }
  50%      { opacity:0.7; box-shadow:0 0 0 6px rgba(62,178,240,0); }
}

/* FIX: war 0.48rem → zu klein
   → 0.56rem + weight:500 + #fff → 21:1 AAA auf dunklem Overlay ✓ */
.hp-stand__hero-badge-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.56rem;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #ffffff;               /* 21:1 AAA auf rgba(0,0,0,0.5) Overlay ✓ */
}

/* H3 SEO: Stadtname + Keyword */
/* #ffffff auf sehr dunklem Overlay (~0.96 black) → 21:1 AAA ✓ */
.hp-stand__hero-city {
  font-size: clamp(3.2rem, 5.5vw, 5rem);
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 0.92;
  color: #ffffff;
  text-shadow: 0 2px 40px rgba(0,0,0,0.5);
}

/* FIX: font-weight:400 statt 300; rgba(255,255,255,0.85) auf Overlay → ~14:1 AAA ✓ */
.hp-stand__hero-sub {
  font-size: 0.85rem;
  font-weight: 400;             /* FIX: war 300 */
  color: rgba(255,255,255,0.85);
  line-height: 1.75;
  max-width: 380px;
}

/* <address> semantisch korrekt + kontrastfest */
/* FIX: rgba(255,255,255,0.70) statt 0.55 → sicherer AA auf tiefem Overlay ✓ */
.hp-stand__hero-address {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.62rem;           /* FIX: war 0.60rem — etwas größer für AA */
  font-weight: 400;
  letter-spacing: 0.1em;
  color: rgba(255,255,255,0.78);
  line-height: 1.8;
  font-style: normal;           /* <address> ist italic by default */
}

/* Service-Tags: <ul><li> semantisch */
.hp-stand__hero-services {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  list-style: none;
  padding: 0;
}

/* FIX: war 0.46rem + weight undef → FAIL Risiko
   → 0.54rem + weight:500 + rgba(255,255,255,0.9) → ~15:1 AAA ✓ */
.hp-stand__hero-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.54rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.22);
  padding: 0.32rem 0.7rem;
  color: rgba(255,255,255,0.92);
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}
/* Hover-Tag: Blau-Tint — accent auf dunklem Overlay bleibt lesbar */
.hp-stand__hero:hover .hp-stand__hero-tag {
  background: rgba(62,178,240,0.15);
  border-color: rgba(62,178,240,0.4);
  color: rgb(62,178,240);       /* auf sehr dunklem Overlay: ~5.5:1 AA ✓ */
}

/* CTA: aria-hidden — Link-Info im aria-label des <a> */
.hp-stand__hero-cta {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.92);
  padding-top: 1.2rem;
  border-top: 1px solid rgba(255,255,255,0.12);
  transition: gap 0.25s, color 0.2s;
}
.hp-stand__hero:hover .hp-stand__hero-cta { gap: 1rem; color: #fff; }
.hp-stand__hero-cta svg { width: 14px; height: 14px; }

/* ══════════════════════════════════════════
   FILIALEN — HELL / WEISSE KARTEN
══════════════════════════════════════════ */
.hp-stand__stack {
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border-top: 4px solid var(--blue-d); /* FIX: --blue-m wäre 2.9:1 FAIL als Akzent sichtbar */
}

.hp-stand__card {
  background: #fff;
  border-bottom: 1px solid rgba(9,58,126,0.07);
  padding: 2.2rem 2.4rem;
  text-decoration: none;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  position: relative;
  overflow: hidden;
  transition: background 0.2s, padding-left 0.25s;
  flex: 1;
}
.hp-stand__card:last-child { border-bottom: none; }

/* Blauer Balken links beim Hover */
.hp-stand__card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom, var(--blue-d), var(--blue-m));
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.3s;
}
.hp-stand__card:hover { background: #f7f9fc; padding-left: 2.8rem; }
.hp-stand__card:hover::before { transform: scaleY(1); }

.hp-stand__card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.hp-stand__card-dot-row { display: flex; align-items: center; gap: 0.45rem; }
/* Dot: dekorativ → aria-hidden */
.hp-stand__card-dot {
  width: 5px; height: 5px;
  background: var(--blue-d);   /* FIX: war --blue-m = dekorativ aber konsistent mit Streifen */
  border-radius: 50%;
  animation: stand-pulse 2.5s ease-in-out infinite;
  flex-shrink: 0;
}

/* rgb(72,87,112) auf #fff → 5.5:1 AA ✓ */
.hp-stand__card-type {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.5rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

/* FIX: war rgba(9,58,126,0.2) = 1.8:1 FAIL → dekorativ → aria-hidden */
.hp-stand__card-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.46rem;
  letter-spacing: 0.1em;
  color: rgba(9,58,126,0.18);  /* dekorativ, aria-hidden im Markup */
}

/* H3 SEO: Stadtname */
/* rgb(12,22,40) → 18:1 AAA ✓ */
.hp-stand__card-city {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.045em;
  line-height: 0.95;
  color: var(--text);
  transition: color 0.2s;
}
/* FIX: hover war --blue-m = 2.9:1 FAIL → --blue-d = 8.2:1 AAA ✓ */
.hp-stand__card:hover .hp-stand__card-city { color: var(--blue-d); }

/* <address>: font-style:normal */
/* rgb(72,87,112) → 5.5:1 AA ✓ */
.hp-stand__card-address {
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.65;
  font-style: normal;
}

/* Service-Chips: <ul><li> semantisch */
.hp-stand__card-services {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  margin-top: auto;
  list-style: none;
  padding: 0;
}
/* rgb(9,58,126) auf rgba(9,58,126,0.05)≈#fff → 8.2:1 AAA ✓ */
.hp-stand__card-service {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.46rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--blue-d);
  background: rgba(9,58,126,0.05);
  border: 1px solid rgba(9,58,126,0.1);
  padding: 0.25rem 0.6rem;
  transition: background 0.2s, border-color 0.2s;
}
.hp-stand__card:hover .hp-stand__card-service {
  background: rgba(9,58,126,0.09);
  border-color: rgba(9,58,126,0.2);
}

/* CTA: aria-hidden — Link-Info im aria-label des <a> */
/* FIX: hover war --blue-m = 2.9:1 FAIL → bleibt --blue-d ✓ */
.hp-stand__card-cta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.52rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--blue-d);          /* 8.2:1 AAA ✓ */
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding-top: 0.9rem;
  border-top: 1px solid rgba(9,58,126,0.07);
  margin-top: 0.2rem;
  transition: gap 0.2s;
}
.hp-stand__card:hover .hp-stand__card-cta { gap: 0.8rem; } /* Farbe bleibt --blue-d ✓ */
.hp-stand__card-cta svg { width: 11px; height: 11px; }

/* ── ANIMATIONEN ── */
.hp-stand__anim { opacity:0;transform:translateY(18px);transition:opacity 0.75s ease,transform 0.75s ease; }
.hp-stand__anim.hp-stand__vis { opacity:1;transform:none; }
.hp-stand__anim--d1 { transition-delay:0.04s; }
.hp-stand__anim--d2 { transition-delay:0.10s; }
.hp-stand__anim--d3 { transition-delay:0.18s; }
.hp-stand__anim--d4 { transition-delay:0.26s; }
.hp-stand__anim--d5 { transition-delay:0.34s; }

/* ── RESPONSIVE ── */
@media (max-width:960px) {
  .hp-stand__layout { grid-template-columns:1fr; }
  .hp-stand__hero { min-height:480px; }
  .hp-stand__stack { border-top:none;border-left:4px solid var(--blue-d);flex-direction:row; }
  .hp-stand__card { border-bottom:none;border-right:1px solid rgba(9,58,126,0.07); }
  .hp-stand__card:last-child { border-right:none; }
}
@media (max-width:640px) {
  .hp-stand__inner { padding:4rem 1.2rem 5rem; }
  .hp-stand__stack { flex-direction:column;border-left:none;border-top:4px solid var(--blue-d); }
  .hp-stand__card { border-right:none;border-bottom:1px solid rgba(9,58,126,0.07); }
  .hp-stand__header { flex-direction:column;align-items:flex-start;gap:1rem; }
  .hp-stand__header-stat { text-align:left; }
  .hp-stand__hero-city { font-size:3rem; }
  .hp-stand__hero-content { padding:2rem 1.8rem 2rem 2.2rem; }
}
