        </style><div style="pointer-events:auto;width:100%;display:block"><div class="custom_code_wrapper"><div class="custom_code_container"><style>
.hp-cta__wrap {
  --red:      rgb(255,0,6);
  --blue-d:   rgb(9,58,126);
  --blue-l:   rgb(62,178,240);
  --text:     rgb(18,30,52);
  --muted:    rgb(72,87,112);
  --subtle:   rgb(109,132,179);
  --border:   rgba(9,58,126,0.08);
  --bg:       #F4F6F9;            /* Kühles Hellgrau — passt zur Seiten-Palette */
  font-family: 'Space Grotesk', sans-serif;
  -webkit-font-smoothing: antialiased;
  width: 100%;
  position: relative;
  overflow: hidden;
  background: var(--bg);
}
.hp-cta__wrap *,
.hp-cta__wrap *::before,
.hp-cta__wrap *::after { box-sizing: border-box; margin: 0; padding: 0; }
.hp-cta__wrap *:focus-visible { outline: 2px solid var(--blue-d); outline-offset: 3px; }

/* ── DEKORATIVE HINTERGRUNDEBENEN ── */

/* Subtiles Grid */
.hp-cta__bg-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(9,58,126,0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(9,58,126,0.035) 1px, transparent 1px);
  background-size: 52px 52px;
  pointer-events: none;
}

/* Großer blauer Glow-Kreis oben-links — zieht Auge auf den CTA */
.hp-cta__bg-glow {
  position: absolute;
  top: -120px; left: -80px;
  width: 560px; height: 560px;
  background: radial-gradient(circle, rgba(9,58,126,0.09) 0%, transparent 65%);
  pointer-events: none;
}

/* Roter Akzent unten-rechts (komplementär) */
.hp-cta__bg-red {
  position: absolute;
  bottom: -80px; right: 5%;
  width: 320px; height: 320px;
  background: radial-gradient(circle, rgba(255,0,6,0.06) 0%, transparent 65%);
  pointer-events: none;
}

/* Hellblauer Glow mittig-rechts */
.hp-cta__bg-blue-r {
  position: absolute;
  top: 20%; right: 35%;
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(62,178,240,0.08) 0%, transparent 60%);
  pointer-events: none;
}

/* Vertikale Trennlinie Text/Bild */
.hp-cta__bg-divider {
  position: absolute;
  top: 0; right: 38%;
  width: 1px; height: 100%;
  background: linear-gradient(to bottom,
    transparent 0%,
    rgba(9,58,126,0.12) 20%,
    rgba(9,58,126,0.20) 50%,
    rgba(9,58,126,0.12) 80%,
    transparent 100%
  );
  pointer-events: none;
}

/* Oberste Trennlinie — kräftiger Blau-Balken */
.hp-cta__bg-top-bar {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg,
    transparent 0%,
    var(--blue-d) 20%,
    var(--blue-l) 50%,
    var(--red) 80%,
    transparent 100%
  );
}

/* ── SPLIT LAYOUT ── */
.hp-cta__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 0;
  align-items: stretch;
  min-height: 580px;
}

/* ── LINKE SPALTE ── */
.hp-cta__content {
  padding: 7rem 4rem 7rem 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0;
}

/* Eyebrow — dunkelblau auf hellem Grund */
.hp-cta__eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.58rem;
  font-weight: 500;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--red);
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 1.2rem;
}
.hp-cta__eyebrow::before,
.hp-cta__eyebrow::after { content:''; width:20px; height:2px; background:var(--red); }

/* H2 — dunkel auf hell */
.hp-cta__h2 {
  font-size: clamp(2.2rem, 3.5vw, 3.4rem);
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 1.0;
  color: var(--text);
  margin-bottom: 1.4rem;
}
.hp-cta__h2 span {
  background: linear-gradient(90deg, var(--blue-d), var(--blue-l));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Sub */
.hp-cta__sub {
  font-size: 0.92rem;
  font-weight: 400;
  color: var(--muted);
  line-height: 1.85;
  max-width: 480px;
  margin-bottom: 2.8rem;
}

/* ── BUTTONS ── */
.hp-cta__btns {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

/* Primär: Rot — bleibt als starker CTA-Akzent */
.hp-cta__btn-primary {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.9rem;
  font-weight: 600;
  color: #fff;
  background: var(--red);
  border: 2px solid var(--red);
  padding: 1rem 2.2rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  box-shadow: 0 4px 20px rgba(255,0,6,0.2);
}
.hp-cta__btn-primary:hover {
  background: rgb(200,0,5);
  transform: translateY(-2px);
  box-shadow: 0 8px 28px rgba(255,0,6,0.28);
}
.hp-cta__btn-primary svg { width:14px; height:14px; transition:transform 0.2s; }
.hp-cta__btn-primary:hover svg { transform: translateX(3px); }

/* Sekundär: Navyblau auf hellem Grund */
.hp-cta__btn-secondary {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--blue-d);
  background: transparent;
  border: 2px solid rgba(9,58,126,0.30);
  padding: 1rem 2.2rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  transition: border-color 0.2s, background 0.2s, transform 0.15s;
}
.hp-cta__btn-secondary:hover {
  border-color: var(--blue-d);
  background: rgba(9,58,126,0.06);
  transform: translateY(-2px);
}
.hp-cta__btn-secondary svg { width:14px; height:14px; transition:transform 0.2s; }
.hp-cta__btn-secondary:hover svg { transform: translateX(3px); }

/* ── TRUST-LISTE ── */
.hp-cta__trust {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  list-style: none;
  padding: 0;
  border-top: 1px solid rgba(9,58,126,0.10);
  padding-top: 1.8rem;
}
.hp-cta__trust-item {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.56rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--subtle);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.hp-cta__trust-item::before {
  content: '';
  width: 4px; height: 4px;
  background: var(--blue-l);
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── RECHTE SPALTE: BILD + ZITAT ── */
.hp-cta__visual {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.hp-cta__img-wrap {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.hp-cta__img {
  width: 100%; height: 100%;
  object-fit: cover;
  object-position: center top;
  display: block;
  /* Hell-Version: weniger stark gedimmt */
  filter: brightness(0.80) saturate(0.85);
  transition: filter 0.5s ease;
}
/* Overlay: leichter am oberen Rand, kräftiger unten für Zitat */
.hp-cta__img-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(244,246,249,0.08) 0%,
    rgba(18,30,52,0.15) 40%,
    rgba(18,30,52,0.88) 100%
  );
}
/* Linker Rand-Gradient — passend zur hellen Seite */
.hp-cta__img-fade {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to right,
    rgba(244,246,249,0.55) 0%,
    transparent 30%
  );
}
/* Blauer Akzent-Streifen rechts */
.hp-cta__img-accent {
  position: absolute;
  top: 0; right: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom,
    transparent 0%,
    var(--blue-d) 30%,
    var(--blue-l) 70%,
    transparent 100%
  );
}

/* ── ZITAT-BLOCK ── */
.hp-cta__quote {
  position: relative;
  z-index: 2;
  padding: 2rem 2rem 2.5rem 2.5rem;
  background: linear-gradient(to top,
    rgba(18,30,52,0.95) 0%,
    rgba(18,30,52,0.0) 100%
  );
}
.hp-cta__quote-mark {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 3.5rem;
  font-weight: 700;
  color: rgba(62,178,240,0.30);
  line-height: 0.8;
  margin-bottom: 0.6rem;
  display: block;
}
.hp-cta__quote-text {
  font-size: 0.88rem;
  font-weight: 400;
  color: rgba(255,255,255,0.80);
  line-height: 1.75;
  font-style: italic;
  margin-bottom: 1.2rem;
  max-width: 340px;
}
.hp-cta__quote-divider {
  width: 32px; height: 2px;
  background: linear-gradient(90deg, var(--blue-d), var(--blue-l));
  margin-bottom: 1rem;
}
.hp-cta__quote-name {
  font-size: 0.82rem;
  font-weight: 700;
  color: rgba(255,255,255,0.95);
  letter-spacing: -0.01em;
  display: block;
  margin-bottom: 0.2rem;
  font-style: normal;
}
.hp-cta__quote-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.52rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
  display: block;
  font-style: normal;
}

/* ── ANIMATIONEN ── */
.hp-cta__anim { opacity:0; transform:translateY(16px); transition:opacity 0.7s ease, transform 0.7s ease; }
.hp-cta__anim.hp-cta__vis { opacity:1; transform:none; }
.hp-cta__anim--d1 { transition-delay:0.05s; }
.hp-cta__anim--d2 { transition-delay:0.14s; }
.hp-cta__anim--d3 { transition-delay:0.22s; }
.hp-cta__anim--d4 { transition-delay:0.30s; }
.hp-cta__visual-anim { opacity:0; transform:translateX(24px); transition:opacity 0.9s ease, transform 0.9s ease; transition-delay:0.10s; }
.hp-cta__visual-anim.hp-cta__vis { opacity:1; transform:none; }

/* ── RESPONSIVE ── */
@media (max-width: 960px) {
  .hp-cta__inner { grid-template-columns: 1fr; min-height: auto; }
  .hp-cta__content { padding: 5rem 0 3rem; order: 2; }
  .hp-cta__visual { order: 1; min-height: 420px; }
  .hp-cta__visual-anim { transform: translateY(-16px); }
  .hp-cta__bg-divider { display: none; }
  .hp-cta__img-fade { background: linear-gradient(to top, rgba(244,246,249,0.3) 0%, transparent 40%); }
  .hp-cta__sub { max-width: 100%; }
}
@media (max-width: 600px) {
  .hp-cta__content { padding: 4rem 0 3.5rem; }
  .hp-cta__visual { min-height: 340px; }
  .hp-cta__btns { flex-direction: column; align-items: stretch; }
  .hp-cta__trust { gap: 0.45rem; }
  .hp-cta__quote { padding: 1.5rem 1.5rem 2rem; }
  .hp-cta__h2 { font-size: clamp(1.9rem, 7vw, 2.8rem); }
}
</style>

